/* GENERATED by tools/content-import.ts. Do not edit. Scripted scenes, band B2. r = scene requirements (focus nodes plus g:/x: nodes in two or more npc lines; nothing from accepts), d = legal day (null = never served), review = needs rewriting. */
window.SCENES_B2 = [
{"id":"sc-u42-a","unit":"u42","band":"B2","title":"Una llamada a la notaría","brief":"You're Tomás, calling the notary's office about Rosa's house. The receptionist doesn't know you, and the notary, Doctor Arciniegas, is a very formal man, so use usted all the way through. Get put through, leave a message, and say thank you properly.","turns":[{"id":"t1","npc":"Marta: Notaría Cuarta, buenos días. ¿En qué le puedo ayudar?","npcEn":"Marta: Fourth Notary's Office, good morning. How can I help you?","intent":"Greet her and ask her, politely and formally, to put you through to Doctor Arciniegas.","accept":["Buenos días. ¿Me comunica con el doctor Arciniegas, por favor?","Buenos días, señorita. ¿Me podría comunicar con el doctor Arciniegas?","Buenas. Necesito hablar con el doctor Arciniegas. ¿Me comunica con él, por favor?"],"require":[{"type":"regex","pattern":"\\bcomunic\\p{L}*\\s+con\\b","flags":"iu","label":"ask: ¿me comunica con...?"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:me-comunica-con","next":"t2"},{"id":"t2","npc":"Marta: Permítame un momento. El doctor está en reunión. ¿Quiere dejarle un mensaje?","npcEn":"Marta: Just a moment, please. The doctor is in a meeting. Would you like to leave him a message?","intent":"Say yes, and ask her to have him call you back as soon as possible.","accept":["Sí, dígale que me llame lo antes posible.","Sí, por favor. Pídale que me llame lo antes posible.","Sí. Le agradecería que me llamara lo antes posible."],"require":[{"type":"regex","pattern":"\\blo antes posible\\b","flags":"iu","label":"include: lo antes posible"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:lo-antes-posible","next":"t3"},{"id":"t3","npc":"Marta: ¿Es por lo del contrato de doña Rosa?","npcEn":"Marta: Is it about the matter of Doña Rosa's contract?","intent":"Say yes, it's about that matter (lo de…), and that Rosa was your grandmother.","accept":["Sí, es por lo del contrato. Doña Rosa era mi abuela.","Sí, señorita, es por lo del contrato de mi abuela Rosa.","Sí, claro, por lo del contrato. Mi abuela era doña Rosa."],"require":[{"type":"regex","pattern":"\\blo del\\b","flags":"iu","label":"refer to the matter with: lo del..."},{"type":"containsWord","word":"abuela","label":"mention your grandmother"}],"focus":"p:lo-de-topic","next":"t4"},{"id":"t4","npc":"Marta: Lo que pasa es que el doctor viaja mañana, pero yo le paso su mensaje hoy mismo.","npcEn":"Marta: The thing is, the doctor is travelling tomorrow, but I'll pass your message on to him today.","intent":"Thank her warmly and formally for her help, with agradecer.","accept":["Se lo agradezco mucho, señorita.","Le agradezco mucho su ayuda.","Muchas gracias. Se lo agradezco de verdad."],"require":[{"type":"regex","pattern":"\\b(se lo|le)\\s+agradezco\\b","flags":"iu","label":"thank her with usted: se lo agradezco / le agradezco"}],"focus":"p:te-lo-agradezco","next":"t5"},{"id":"t5","npc":"Marta: Con mucho gusto. Que le vaya bien.","npcEn":"Marta: My pleasure. Take care.","intent":"Say goodbye and ask her to pass your greetings to the doctor (formal).","accept":["Hasta luego. Salúdelo de mi parte, por favor.","Adiós, y dele saludos al doctor de mi parte.","Que esté bien. Dele saludos de mi parte al doctor."],"require":[{"type":"regex","pattern":"\\bde mi parte\\b","flags":"iu","label":"include: de mi parte"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:saludos-de-mi-parte","next":null}],"r":["g:gender-articles","p:lo-antes-posible","p:lo-de-topic","p:me-comunica-con","p:saludos-de-mi-parte","p:te-lo-agradezco"],"d":471},
{"id":"sc-u42-b","unit":"u42","band":"B2","title":"El informe del laboratorio","brief":"You're Tomás at the counter of the court, speaking to the judge's clerk. Nothing here is casual: you need to be more formal than with the notary, soften every request, and stay friendly. Try to see the lab report, and leave with a plan.","turns":[{"id":"t1","npc":"Secretario: Buenas tardes. Dígame, ¿en qué puedo servirle?","npcEn":"Clerk: Good afternoon. Tell me, how can I help you?","intent":"Greet him and softly ask whether the lab report has arrived yet (start with 'quería' or '¿será que...?').","accept":["Buenas tardes. Quería preguntarle si ya llegó el informe del laboratorio.","Buenas tardes. Quería saber si el informe del laboratorio ya llegó.","Buenas tardes. ¿Será que ya llegó el informe del laboratorio?"],"require":[{"type":"regex","pattern":"\\b(quería|será que)\\b","flags":"iu","label":"soften it: quería... / ¿será que...?"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:softening","next":"t2"},{"id":"t2","npc":"Secretario: Llegó esta mañana, sí. Pero está prohibido mostrarlo sin la firma del juez.","npcEn":"Clerk: It arrived this morning, yes. But it is forbidden to show it without the judge's signature.","intent":"Ask whether it would be possible to read it today, here at the counter.","accept":["Entiendo. ¿Sería posible leerlo hoy aquí mismo?","Entiendo. ¿Sería posible leerlo hoy, aquí en el mostrador?","Claro. ¿Sería posible verlo hoy, sin llevármelo?"],"require":[{"type":"regex","pattern":"\\bsería posible\\b","flags":"iu","label":"ask with: ¿sería posible...?"},{"type":"question","label":"ask a question"}],"focus":"p:seria-posible","next":"t3"},{"id":"t3","npc":"Secretario: Tendría que pedírselo al juez, y sale de la sala a las cuatro. ¿Puede esperar una hora?","npcEn":"Clerk: You would have to ask the judge, and he comes out of the courtroom at four. Can you wait an hour?","intent":"Say politely that you can't, you don't have time today (no me alcanza el tiempo / no me da tiempo), and give a reason.","accept":["Lo siento, hoy no me alcanza el tiempo para esperar tanto. Tengo que abrir el café.","Qué pena, pero hoy no me da tiempo de esperar una hora.","Ay, no me alcanza el tiempo hoy. Tengo que estar en el café a las cinco."],"require":[{"type":"regex","pattern":"\\bno me (da|alcanza|dio)\\b.*\\btiempo\\b|\\bno me (alcanza|alcanzó) el tiempo\\b","flags":"iu","label":"say you don't have time: no me da tiempo / no me alcanza el tiempo"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:dar-tiempo","next":"t4"},{"id":"t4","npc":"Secretario: Entonces le anoto una cita con el juez para el jueves a las ocho.","npcEn":"Clerk: Then I'll put you down for an appointment with the judge on Thursday at eight.","intent":"Tell him that is very kind of him (formal) and that Thursday at eight works for you.","accept":["Muy amable de su parte. El jueves a las ocho me queda perfecto.","Qué amable de su parte. Ahí estaré el jueves.","Es muy amable de su parte. Jueves a las ocho, perfecto."],"require":[{"type":"regex","pattern":"\\bamable de su parte\\b","flags":"iu","label":"say: amable de su parte"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:amable-de-su-parte","next":"t5"},{"id":"t5","npc":"Secretario: Una cosa más: está prohibido que entre con el celular a la sala.","npcEn":"Clerk: One more thing: it is forbidden to bring your mobile phone into the courtroom.","intent":"Tell him there's no need for him to remind you, you'll leave it at the café, and say see you Thursday.","accept":["No hace falta que me lo diga otra vez, señor. Lo dejo en el café. Hasta el jueves.","No hace falta que me lo repita. Lo dejaré en el café. Nos vemos el jueves.","Entendido. No hace falta que insista, lo dejo en el café. Hasta el jueves."],"require":[{"type":"regex","pattern":"\\bno hace falta que\\b","flags":"iu","label":"say: no hace falta que... (no need for you to...)"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"x:no-hace-falta-vs-prohibido","next":null}],"r":["g:estar-location-states","g:gender-articles","g:indirect-objects","g:object-pronoun-position","g:softening","g:stem-boot","g:verb-infinitive","p:amable-de-su-parte","p:dar-tiempo","p:seria-posible","x:no-hace-falta-vs-prohibido"],"d":457},
{"id":"sc-u42-c","unit":"u42","band":"B2","title":"El carro de Camilo","brief":"You're Tomás at the garage where Hernando's old taxi gets fixed. Camilo, the mechanic, is your age and by now a friend, so use tú and keep it warm. You need to borrow his car on Saturday to move the espresso machine, and he is going to make you earn it.","turns":[{"id":"t1","npc":"Camilo: ¡Tomás! Cuánto tiempo sin verte por el taller. ¿Se volvió a dañar la Burra?","npcEn":"Camilo: Tomás! It's been so long since I saw you at the garage. Has the Burra broken down again?","intent":"Ask him, as a friend, whether he would do you a favour.","accept":["Camilo, ¿me harías un favor?","Hola, Camilo. Necesito pedirte algo. ¿Me harías un favor?","No, tranquilo. ¿Me harías un favor, Camilo?"],"require":[{"type":"regex","pattern":"\\bme harías un favor\\b","flags":"iu","label":"ask: ¿me harías un favor?"},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"p:me-harias-un-favor","next":"t2"},{"id":"t2","npc":"Camilo: Depende. ¿De qué se trata?","npcEn":"Camilo: Depends. What is it about?","intent":"Say that Vale told you to ask him for the car on Saturday.","accept":["Vale me dijo que te pidiera el carro el sábado.","Es que Vale me dijo que te pidiera el carro prestado para el sábado.","Vale me pidió que te pidiera el carro, Camilo. Es para el sábado."],"require":[{"type":"regex","pattern":"\\bme (dijo|pidió|aconsejó) que\\s+(?:(?:me|te|se|le|lo|la|nos)\\s+){0,2}\\p{L}*(ara|iera)\\b","flags":"iu","label":"report it: Vale me dijo que + te pidiera..."},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"g:reported-commands-past","next":"t3"},{"id":"t3","npc":"Camilo: ¿Y qué vas a hacer con él?","npcEn":"Camilo: And what are you going to do with it?","intent":"Say you need it to move the espresso machine, and ask him to lend it to you.","accept":["Necesito llevar la máquina de espresso al café. ¿Me lo prestas?","Tengo que mover la máquina de café el sábado. ¿Me prestas el carro?","Es para mover la máquina. Necesito que me prestes el carro."],"require":[{"type":"regex","pattern":"\\bprest(as|es|ar)\\b","flags":"iu","label":"ask to borrow it: ¿me lo prestas?"},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"g:register-ladder","next":"t4"},{"id":"t4","npc":"Camilo: Ya veremos. Ese carro huele raro desde el martes, creo que es el combustible.","npcEn":"Camilo: We'll see. That car has smelled strange since Tuesday, I think it's the fuel.","intent":"Offer to help him look at it (Déjame que...).","accept":["Déjame que te ayude a revisarlo.","Déjame que te ayude con eso, Camilo.","Déjame que te ayude, no me cuesta nada."],"require":[{"type":"regex","pattern":"\\bdéjame (que te ayude|ayudarte)\\b","flags":"iu","label":"offer help: déjame que te ayude"},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"p:dejame-que-te-ayude","next":"t5"},{"id":"t5","npc":"Camilo: No hace falta, yo lo arreglo. Bueno, si no hay más remedio, te lo presto, pero que sea la última vez que me lo devuelvas sin combustible.","npcEn":"Camilo: There's no need, I'll fix it. Well, if there's no other way, I'll lend it to you, but let it be the last time you give it back to me with no fuel.","intent":"Promise it's the last time, and say you don't know how to thank him.","accept":["Te lo prometo. No sé cómo agradecértelo.","Palabra. Es la última vez, y no sé cómo agradecértelo, de verdad.","Prometido, Camilo. No sé cómo agradecértelo."],"require":[{"type":"regex","pattern":"\\bagradecértelo\\b","flags":"iu","label":"say: no sé cómo agradecértelo"},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"c:no-se-como-agradecertelo","next":"t6"},{"id":"t6","npc":"Camilo: Cuando quieras pasas por las llaves. Eso sí, me lo devuelves entero.","npcEn":"Camilo: Come by for the keys whenever you like. Just give it back to me in one piece.","intent":"Say you'll pick up the keys tomorrow at nine, and wish for it all to go well (crucemos los dedos).","accept":["Mañana a las nueve paso por las llaves. Crucemos los dedos para que todo salga bien.","Paso por ellas mañana a las nueve. Crucemos los dedos para que el carro vuelva entero.","Mañana temprano paso. Y crucemos los dedos para que todo salga bien."],"require":[{"type":"regex","pattern":"\\bcrucemos los dedos\\b","flags":"iu","label":"include: crucemos los dedos"},{"type":"avoidsAny","words":["usted"],"label":"use tú with a friend, not usted"}],"focus":"c:crucemos-los-dedos","next":null}],"r":["c:crucemos-los-dedos","c:no-se-como-agradecertelo","g:direct-objects","g:double-pronouns","g:gender-articles","g:por-para-1","g:present-ar","g:register-ladder","g:reported-commands-past","p:dejame-que-te-ayude","p:me-harias-un-favor"],"d":null,"spare":true},
{"id":"sc-u42-d","unit":"u42","band":"B2","title":"La grabadora de Altamira","brief":"You're Tomás, sitting across from Ricardo Altamira's polished assistant, Paola Rey. A recorder sits on the table and everything you say is on the record. Stay formal, stay polite, smile, and still get your point across.","turns":[{"id":"t1","npc":"Paola: Buenas tardes, señor Herrera. Le aviso que esta conversación queda grabada. ¿Le parece bien?","npcEn":"Paola: Good afternoon, Mr Herrera. I should let you know that this conversation is being recorded. Is that all right with you?","intent":"Say that is fine, and ask permission to make a comment before you begin.","accept":["Está bien. Antes de empezar, ¿me permite un comentario?","Por mí no hay problema. ¿Me permite un comentario primero?","Claro. ¿Me permite un comentario antes de empezar?"],"require":[{"type":"regex","pattern":"\\bme permit\\p{L}*\\s+(hacer\\s+)?un comentario\\b","flags":"iu","label":"ask: ¿me permite un comentario?"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:puedo-hacerte-una-pregunta","next":"t2"},{"id":"t2","npc":"Paola: Por supuesto, dígame.","npcEn":"Paola: Of course, go ahead.","intent":"Begin with 'to be honest' (formal) and say you don't find it appropriate to buy the whole block without talking to the neighbours.","accept":["Para serle sincero, no me parece apropiado comprar toda la cuadra sin hablar con los vecinos.","Para serle sincero, creo que no es apropiado comprar la cuadra sin hablar antes con los vecinos.","Para serle sincero, no es lo más apropiado comprar todo sin hablar con los vecinos."],"require":[{"type":"regex","pattern":"\\bpara serle sincer[oa]\\b","flags":"iu","label":"start with: para serle sincero"},{"type":"containsAny","words":["apropiado","apropiada","adecuado"],"label":"use apropiado"}],"focus":"c:para-serte-sincero","next":"t3"},{"id":"t3","npc":"Paola: Entiendo su posición. El señor Altamira estaría encantado de recibirlo. ¿Le propongo una reunión con él?","npcEn":"Paola: I understand your position. Mr Altamira would be delighted to receive you. Shall I suggest a meeting with him?","intent":"Say yes, and ask her to arrange it soon, starting with 'Le agradecería que...'.","accept":["Me parece bien. Le agradecería que organizara la reunión lo antes posible.","Sí. Le agradecería que me consiguiera una cita con él esta semana.","Perfecto. Le agradecería que me recibiera con mis vecinos."],"require":[{"type":"regex","pattern":"\\ble agradecería que\\s+(?:(?:me|te|se|le|lo|la|nos)\\s+){0,2}\\p{L}*(ara|iera)\\b","flags":"iu","label":"start with: le agradecería que + imperfect subjunctive"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:le-agradeceria-que","next":"t4"},{"id":"t4","npc":"Paola: Entonces confirmo que usted viene solo y retira la solicitud del laboratorio.","npcEn":"Paola: Then I'll confirm that you are coming alone and withdrawing the request for the lab.","intent":"Correct her politely: you did not say that, and you are not withdrawing the request.","accept":["Disculpe, pero yo no dije eso. No voy a retirar la solicitud.","Perdone, pero yo nunca dije eso, y no pienso retirar la solicitud.","No, señorita, eso no lo dije. La solicitud sigue en pie."],"require":[{"type":"negation","label":"correct her with a negative"},{"type":"regex","pattern":"\\b(no|nunca)\\s+(lo\\s+)?(he dicho|dije)\\b","flags":"iu","label":"say you didn't say it: no dije eso"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:register-ladder","next":"t5"},{"id":"t5","npc":"Paola: Tiene razón, me equivoqué. Entonces, el lunes a las diez, ¿le parece bien?","npcEn":"Paola: You are right, I made a mistake. So, Monday at ten, does that suit you?","intent":"Accept Monday at ten, thank her, and wish her the best (le deseo lo mejor).","accept":["Me parece bien, el lunes a las diez. Muchas gracias, y le deseo lo mejor.","Perfecto. Hasta el lunes, y le deseo lo mejor.","El lunes a las diez está bien. Le deseo lo mejor, Paola."],"require":[{"type":"regex","pattern":"\\ble deseo lo mejor\\b","flags":"iu","label":"include: le deseo lo mejor"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"c:le-deseo-lo-mejor","next":null}],"r":["c:le-deseo-lo-mejor","c:para-serte-sincero","g:gender-articles","g:indirect-objects","g:parecer-quedar","g:present-ar","g:present-er-ir","g:register-ladder","g:stem-boot","g:that-clauses","p:le-agradeceria-que","p:puedo-hacerte-una-pregunta"],"d":null,"spare":true},
{"id":"sc-u42-e","unit":"u42","band":"B2","title":"Simón y la cortesía","brief":"You're Tomás in the café after closing. Don Hernando, courtly as always, is worried: Simón has been bossing the customers around. You are younger and he is older, so use usted with him, and help him teach the parrot some manners.","turns":[{"id":"t1","npc":"Hernando: Tomás, Simón le gritó \"dame pan\" a una clienta. Me da vergüenza.","npcEn":"Hernando: Tomás, Simón shouted \"give me bread\" at a customer. I'm embarrassed.","intent":"Tell him there is no need for him to worry, she laughed.","accept":["No hace falta que se preocupe, don Hernando. Ella se rio.","Tranquilo, don Hernando, no hace falta que se preocupe. Se rio mucho.","No hace falta que se disculpe, don Hernando. Ella se rio."],"require":[{"type":"regex","pattern":"\\bno hace falta que\\b","flags":"iu","label":"say: no hace falta que..."},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:no-hace-falta-que","next":"t2"},{"id":"t2","npc":"Hernando: Aun así, un loro educado no ordena. A ver, usted que sabe: ¿cómo le pediría un pan a una clienta sin que suene a orden?","npcEn":"Hernando: Even so, a polite parrot doesn't give orders. Let's see, you who know: how would you ask a customer for a piece of bread without it sounding like an order?","intent":"Show how: politely ask a customer (usted) for a piece of bread.","accept":["¿Me regala un pan, por favor?","¿Me podría dar un pan, por favor?","¿Será que me puede dar un pan?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:register-ladder","next":"t3"},{"id":"t3","npc":"Hernando: Muy bien. ¿Y si el cliente fuera un juez? Hay que subir un escalón más.","npcEn":"Hernando: Very good. And if the customer were a judge? You have to go up one more rung.","intent":"Ask a judge for some bread in the most formal way, starting with 'Le agradecería que...'.","accept":["Le agradecería que me diera un poco de pan.","Le agradecería que me regalara un pedazo de pan.","Le agradecería que me pasara el pan, señor juez."],"require":[{"type":"regex","pattern":"\\ble agradecería que\\s+(?:(?:me|te|se|le|lo|la|nos)\\s+){0,2}\\p{L}*(ara|iera)\\b","flags":"iu","label":"start with: le agradecería que + imperfect subjunctive"}],"focus":"p:le-agradeceria-que","next":"t4"},{"id":"t4","npc":"Simón: ¡Le agradecería que me diera pan! ¡Le agradecería que me diera pan!\nHernando: ¡Lo aprendió! Pero, ¿dónde?","npcEn":"Simón: I would be grateful if you gave me bread! I would be grateful if you gave me bread!\nHernando: He learned it! But where?","intent":"Say, with a hedge at the end, that he learned it from listening to you two.","accept":["Lo aprendió escuchándonos, supongo.","Simón escucha todo y aprende rápido, imagino.","Lo oyó de nosotros, supongo."],"require":[{"type":"regex","pattern":",\\s*(supongo|imagino)\\s*[.!]?$","flags":"iu","label":"end with the hedge: ..., supongo / ..., imagino"}],"focus":"p:supongo-imagino-tag","next":"t5"},{"id":"t5","npc":"Hernando: Así es. Qué raro, los loros aprenden primero lo malo. Pero venga, permítame invitarle un tinto.","npcEn":"Hernando: That's true. Funny, parrots learn the bad things first. But come, allow me to buy you a black coffee.","intent":"Say that people in general learn the bad things first too, then accept the coffee and thank him.","accept":["Uno también aprende primero lo malo, don Hernando. Con gusto, muchas gracias.","Uno aprende lo malo primero, es cierto. Acepto el tinto, muy amable.","Nos pasa a todos: uno aprende lo malo primero. Gracias, don Hernando."],"require":[{"type":"regex","pattern":"\\buno\\b","flags":"iu","label":"speak generally with: uno..."},{"type":"containsAny","words":["gracias","amable","agradezco"],"label":"thank him"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:generic-tu-uno","next":null}],"r":["g:commands-with-pronouns","g:conditional","g:gender-articles","g:indirect-objects","g:present-er-ir","g:questions","g:register-ladder","g:that-clauses","p:generic-tu-uno","p:le-agradeceria-que","p:no-hace-falta-que","p:supongo-imagino-tag"],"d":null,"spare":true},
{"id":"sc-u42-f","unit":"u42","band":"B2","title":"Doña Gladys y el domicilio","brief":"You're Tomás at the corner shop near the café. Doña Gladys has known the street for fifty years and expects respect, so use usted. Get through the door, arrange a delivery to the café, and make a friend.","turns":[{"id":"t1","npc":"Doña Gladys: Joven, usted es el del café, ¿no? Pasa por aquí todos los días y nunca saluda.","npcEn":"Doña Gladys: Young man, you're the one from the café, aren't you? You go by here every day and you never say hello.","intent":"Apologise politely, address her as doña Gladys, and say you are always in a hurry.","accept":["Tiene razón, doña Gladys. Perdone, siempre voy con mucha prisa.","Perdone, doña Gladys. Siempre voy con prisa, pero desde hoy la saludo.","Doña Gladys, tiene razón. Es que siempre ando con prisa."],"require":[{"type":"regex","pattern":"\\bdoña Gladys\\b","flags":"iu","label":"address her: doña Gladys"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:don-dona-nombre","next":"t2"},{"id":"t2","npc":"Doña Gladys: No hay problema. ¿En qué le puedo servir?","npcEn":"Doña Gladys: No problem. How can I help you?","intent":"Ask her politely whether she could send a delivery to the café tonight.","accept":["¿Será que me puede mandar un domicilio al café esta noche?","¿Me podría mandar un domicilio al café esta noche, por favor?","¿Sería posible pedir un domicilio para el café esta noche?"],"require":[{"type":"regex","pattern":"\\bdomicilio\\b","flags":"iu","label":"mention the delivery: un domicilio"},{"type":"regex","pattern":"\\b(podría|puede|será que|sería posible)\\b","flags":"iu","label":"soften it: ¿podría...? / ¿será que...?"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"c:pedir-un-domicilio","next":"t3"},{"id":"t3","npc":"Doña Gladys: Claro que sí. ¿Y cómo le explico al muchacho dónde queda?","npcEn":"Doña Gladys: Of course. And how do I explain to the boy where it is?","intent":"Give the way as simple steps with the 'we' form, as if you walked it together: up the street to the corner café in La Candelaria.","accept":["Subimos por esta calle y llegamos al café de la esquina, en La Candelaria.","Salimos de aquí, subimos por la calle y entramos al café de la esquina, en La Candelaria.","Primero subimos por la calle y luego buscamos el café de la esquina, en La Candelaria."],"require":[{"type":"containsWord","word":"Candelaria","label":"give the place: La Candelaria"},{"type":"person","person":"nosotros","label":"give the steps with the we form: subimos, llegamos"}],"focus":"p:nosotros-instructions","next":"t4"},{"id":"t4","npc":"Doña Gladys: Ay, usted es el nieto de doña Rosa. Su abuela siempre me pedía que le guardara el pan del domingo.","npcEn":"Doña Gladys: Oh, you're Doña Rosa's grandson. Your grandmother always asked me to save her the Sunday bread.","intent":"Say that your grandmother always told you to go and say hello to her.","accept":["Mi abuela siempre me decía que viniera a saludarla.","La abuela siempre me decía que viniera a visitarla.","Mi abuela me pedía que pasara a saludarla, y nunca vine."],"require":[{"type":"regex","pattern":"\\bme (decía|pedía|aconsejaba) que\\s+(?:(?:me|te|se|le|lo|la|nos)\\s+){0,2}\\p{L}*(ara|iera)\\b","flags":"iu","label":"report it: mi abuela me decía que + viniera..."},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:reported-commands-past","next":"t5"},{"id":"t5","npc":"Doña Gladys: El muchacho llega a las seis. Le deseo lo mejor con el café, joven.","npcEn":"Doña Gladys: The boy arrives at six. I wish you the best with the café, young man.","intent":"Thank her and say you hope to see her again soon.","accept":["Muchas gracias, doña Gladys. Hasta pronto.","Se lo agradezco mucho. Ojalá la vea pronto.","Gracias por todo. Vengo pronto a saludarla."],"require":[{"type":"regex","pattern":"gracias|agradezco","flags":"iu","label":"thank her"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:te-lo-agradezco","next":null}],"r":["c:pedir-un-domicilio","g:gender-articles","g:indirect-objects","g:present-ar","g:reported-commands-past","g:ser-identity","p:don-dona-nombre","p:nosotros-instructions","p:te-lo-agradezco"],"d":473,"spare":true},
{"id":"sc-u43-a","unit":"u43","band":"B2","title":"La carta sin sello","brief":"You're Tomás, in the café after closing with Don Hernando, who has been rereading the letter Rosa never posted in 2009. He is older than you and courtly, so use usted. Say what seemed wrong, what you would have done, and listen kindly.","turns":[{"id":"t1","npc":"Hernando: Tomás, volví a leer la carta de 2009. Rosa la tuvo en la mano y nunca la mandó. Ojalá la hubiera mandado.","npcEn":"Hernando: Tomás, I read the 2009 letter again. Rosa had it in her hand and never sent it. If only she had sent it.","intent":"Say that it seemed wrong to you that Rosa had never sent it.","accept":["Me pareció mal que Rosa no la hubiera mandado nunca.","Sinceramente, me pareció mal que ella nunca la hubiera mandado.","Me pareció muy mal que no la hubiera mandado, Hernando."],"require":[{"type":"regex","pattern":"\\bme pareció (muy |tan )?mal que\\b.*\\bhubier[ao]n?\\b","flags":"iu","label":"say it seemed wrong: me pareció mal que + hubiera..."}],"focus":"p:me-parecio-mal-que","next":"t2"},{"id":"t2","npc":"Ella tenía miedo de la respuesta. ¿Usted la habría mandado en su lugar?","npcEn":"She was afraid of the answer. Would you have sent it in her place?","intent":"Say yes, in her place you would have sent it the same day.","accept":["Yo la habría mandado ese mismo día.","En su lugar, yo la habría mandado enseguida.","Yo habría mandado la carta ese mismo día, sin pensarlo."],"require":[{"type":"regex","pattern":"\\bhabría\\s+\\p{L}+(ado|ido)\\b","flags":"iu","label":"say what you would have done: habría + participle"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:conditional-perfect","next":"t3"},{"id":"t3","npc":"Cuarenta y siete cartas, Tomás, y ninguna salió de esa caja. Ellos nunca volvieron a hablar.","npcEn":"Forty-seven letters, Tomás, and not one left that box. They never spoke again.","intent":"Say that you are very sorry that they had never spoken again.","accept":["Siento mucho que nunca hubieran vuelto a hablar.","Siento mucho que Rosa y Joaquín no hubieran vuelto a hablar.","Siento mucho que no hubieran hablado nunca más."],"require":[{"type":"regex","pattern":"\\b(siento|lamento) mucho que\\b.*\\bhubier[ao]n?\\b","flags":"iu","label":"start with: siento mucho que + hubieran..."}],"focus":"p:siento-mucho-que","next":"t4"},{"id":"t4","npc":"Y hay algo más. Esa mañana de 2009, Rosa me dijo que no, y yo no insistí. ¿Usted habría insistido?","npcEn":"And there is something more. That morning in 2009, Rosa told me no, and I didn't insist. Would you have insisted?","intent":"Say yes, you would have insisted, and taken her to the post office.","accept":["Sí, yo habría insistido y la habría llevado al correo.","Creo que sí. Yo habría insistido un poco más.","Sí, Hernando. Yo habría insistido, con mucho cariño."],"require":[{"type":"regex","pattern":"\\bhabría\\s+insistido\\b","flags":"iu","label":"use habría insistido"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:conditional-perfect","next":"t5"},{"id":"t5","npc":"Gracias por escucharme, Tomás. A Rosa le habría gustado esta conversación. ¿Me regala un tinto?","npcEn":"Thank you for listening, Tomás. Rosa would have liked this conversation. Could I have a black coffee?","intent":"Say you'll gladly bring him a black coffee, and that the house is paying.","accept":["Con gusto, Hernando. Ya le traigo el tinto, invita la casa.","Claro que sí. Ahora mismo le traigo el tinto, y la casa invita.","Con mucho gusto. El tinto lo invita la casa."],"require":[{"type":"regex","pattern":"\\b(tinto|café)\\b","flags":"iu","label":"mention the coffee"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:pluperfect-subj","next":null}],"r":["g:conditional-perfect","g:demonstratives","g:direct-objects","g:gender-articles","g:pluperfect-subj","g:preterite-er-ir","g:preterite-irregular-strong","p:me-parecio-mal-que","p:siento-mucho-que"],"d":375},
{"id":"sc-u43-b","unit":"u43","band":"B2","title":"Dos caminos","brief":"You're Tomás, wiping tables with Vale after a long day. She is quick and dry, and a friend, so use tú. Talk about the Toronto job you turned down and what would have happened, then about how things turned out.","turns":[{"id":"t1","npc":"Vale: Mariana me contó que no aceptaste el trabajo. Si tú hubieras firmado el contrato, ¿dónde estarías ahora?","npcEn":"Vale: Mariana told me you didn't accept the job. If you had signed the contract, where would you be now?","intent":"Say that if you had accepted, you would be in Toronto.","accept":["Si hubiera aceptado, estaría en Toronto.","Estaría en Toronto, claro. Si hubiera aceptado el contrato, no estaría aquí.","Si hubiera aceptado el trabajo, ahora mismo estaría en Toronto, con frío."],"require":[{"type":"regex","pattern":"\\bsi\\b.*\\bhubier[ao]\\b","flags":"iu","label":"use si + hubiera..."}],"focus":"x:si-past-present-unreal","next":"t2"},{"id":"t2","npc":"¿Y el café? Sin ti, ¿qué habría pasado con el café?","npcEn":"And the café? Without you, what would have happened to the café?","intent":"Say that if you had left, the café would have closed.","accept":["Si me hubiera ido, el café habría cerrado.","Si me hubiera ido a Toronto, el café habría cerrado en un mes.","Creo que, si me hubiera ido, el café habría cerrado."],"require":[{"type":"regex","pattern":"\\bsi\\b.*\\bhubier[ao]\\b","flags":"iu","label":"start the condition: si + hubiera..."},{"type":"regex","pattern":"\\bhabría\\s+\\p{L}+(ado|ido)\\b","flags":"iu","label":"finish with: habría + participle"}],"focus":"g:si-past-unreal","next":"t3"},{"id":"t3","npc":"Qué dramático. Pero bueno, a mí venir a Bogotá me salió bien. ¿Y a ti, quedarte?","npcEn":"How dramatic. But hey, coming to Bogotá worked out well for me. And for you, staying?","intent":"Say that staying worked out well for you, and that leaving would have been worse.","accept":["Sí, quedarme me salió bien. Irme habría sido peor.","Me salió muy bien. Irme habría sido un error.","Me salió bien, Vale. Habría sido peor irme."],"require":[{"type":"regex","pattern":"\\bsalió(?!\\p{L})\\s+(muy\\s+)?bien","flags":"iu","label":"say it worked out well: me salió bien"},{"type":"regex","pattern":"\\bhabría sido\\b","flags":"iu","label":"compare with: habría sido..."}],"focus":"p:salirle-bien","next":"t4"},{"id":"t4","npc":"Mira, esa carta de Altamira me asustó. Pensé que el café no iba a sobrevivir a esta crisis.","npcEn":"Look, that letter from Altamira scared me. I thought the café wasn't going to survive this crisis.","intent":"Say the café has survived worse crises before.","accept":["Este café sobrevivió a crisis peores, ya verás.","El café ya sobrevivió a peores crisis. Va a sobrevivir a esta también.","Sobrevivió a crisis peores que esta, Vale."],"require":[{"type":"regex","pattern":"\\bsobreviv\\p{L}*\\s+a\\b","flags":"iu","label":"use sobrevivir a"}],"focus":"p:sobrevivir-a","next":"t5"},{"id":"t5","npc":"Brindo por eso. ¿Y si hago algo dulce para celebrar?","npcEn":"I'll drink to that. What if I make something sweet to celebrate?","intent":"Say yes, and ask her what she is going to make.","accept":["Sí, claro. ¿Qué vas a hacer?","Me encanta la idea. ¿Qué vas a preparar?","Listo, Vale. ¿Qué vas a hacer?"],"require":[{"type":"question"},{"type":"avoidsPerson","person":"ellos","label":"talk to Vale, not about her"}],"focus":"g:si-past-unreal","next":null}],"r":["g:gender-articles","g:prep-pronouns","g:preterite-ar","g:questions","g:si-past-unreal","p:salirle-bien","p:sobrevivir-a","x:si-past-present-unreal"],"d":null},
{"id":"sc-u43-c","unit":"u43","band":"B2","title":"Un viajero con frío","brief":"You're Tomás. Your cousin Yesid has just stepped off the bus from the coast, and he is freezing. He is family and about your age, so use tú. Be kind, make a guess about why his trip went wrong, and warm him up.","turns":[{"id":"t1","npc":"Yesid: Uy, hermano. ¿En Bogotá siempre hace tanto frío?","npcEn":"Yesid: Wow, man. Is it always this cold in Bogotá?","intent":"Say it is almost always cold in the morning, but today is colder than usual.","accept":["Casi siempre por la mañana, pero hoy hace más frío de lo normal.","Por la mañana sí, pero hoy hace más frío que de costumbre.","Sí, por la mañana casi siempre, aunque hoy hace más frío de lo normal."],"require":[{"type":"minWords","n":6}],"focus":"g:softening","next":"t2"},{"id":"t2","npc":"Si hubiera sabido, habría traído un abrigo. Nadie me avisó.","npcEn":"If I had known, I would have brought a coat. Nobody warned me.","intent":"Say that you are very sorry that nobody had warned him.","accept":["Siento mucho que nadie te hubiera avisado.","Siento mucho que nadie te hubiera dicho nada.","Siento mucho que no te hubieran avisado."],"require":[{"type":"regex","pattern":"\\bsiento mucho que\\b.*\\bhubier[ao]n?\\b","flags":"iu","label":"start with: siento mucho que + hubiera..."}],"focus":"p:siento-mucho-que","next":"t3"},{"id":"t3","npc":"Y el bus salió tarde. Si hubiera salido a tiempo, habría llegado de día. ¿Tú qué crees que pasó?","npcEn":"And the bus left late. If it had left on time, I would have arrived in daylight. What do you think happened?","intent":"Guess, with a hedge, that the rain probably closed the road.","accept":["Probablemente cerraron la vía por la lluvia.","Seguramente fue por el temporal.","Tal vez cerraron la vía por la lluvia, no sé."],"require":[{"type":"containsAny","words":["probablemente","seguramente","tal vez","quizás","a lo mejor"],"label":"hedge your guess: probablemente, seguramente, tal vez..."}],"focus":"g:softening","next":"t4"},{"id":"t4","npc":"Qué tonto fui. Pensaba que Bogotá era tropical, ¿sabes?","npcEn":"How silly I was. I thought Bogotá was tropical, you know?","intent":"Say that you would have thought the same, and offer to make him a hot chocolate.","accept":["Yo habría pensado lo mismo. ¿Te preparo un chocolate caliente?","Yo también habría pensado lo mismo. ¿Quieres un chocolate caliente?","Habría pensado lo mismo, no te preocupes. ¿Te preparo un chocolate?"],"require":[{"type":"regex","pattern":"\\bhabría\\s+pensado\\b","flags":"iu","label":"use habría pensado"},{"type":"question"}],"focus":"g:conditional-perfect","next":"t5"},{"id":"t5","npc":"Uf, sí, por favor. ¿Aquí lo sirven con queso, de verdad?","npcEn":"Oh, yes please. Do they really serve it with cheese here?","intent":"Say yes, it comes with cheese, and he is going to like it.","accept":["Sí, con queso. Ya verás, te va a gustar.","Sí, aquí va con queso. Te va a gustar, ya verás.","Claro, con queso. Te va a encantar."],"require":[{"type":"containsWord","word":"queso","label":"mention the cheese"}],"focus":"g:softening","next":null}],"r":["g:conditional-perfect","g:gender-articles","g:pluperfect-subj","g:present-er-ir","g:preterite-ar","g:questions","g:si-hypothetical","g:si-past-unreal","g:softening","g:that-clauses","p:siento-mucho-que"],"d":375,"spare":true},
{"id":"sc-u44-a","unit":"u44","band":"B2","title":"Diez minutos antes","brief":"You're Tomás, waiting outside the hearing room with Yesid, who is helping you prepare. He's your friend, so use tú. Give your view, answer the danger claim with a concession, cite a study and set your condition for any deal.","turns":[{"id":"t1","npc":"Yesid: Entramos en diez minutos. ¿Cuál es tu punto principal?","npcEn":"Yesid: We go in in ten minutes. What is your main point?","intent":"Give your view: the building is part of the city's heritage (use: Desde mi punto de vista, or Considero que).","accept":["Desde mi punto de vista, el edificio es parte del patrimonio de la ciudad.","Considero que el edificio es parte del patrimonio de la ciudad.","Considero que el café tiene mucho valor para el barrio."],"require":[{"type":"regex","pattern":"\\b(desde mi punto de vista|considero que|a mi modo de ver)\\b","flags":"iu","label":"state your view: desde mi punto de vista, considero que"}],"focus":"p:a-mi-modo-de-ver","next":"t2"},{"id":"t2","npc":"Yesid: La abogada de Altamira va a decir que el edificio es peligroso.","npcEn":"Yesid: Altamira's lawyer is going to say that the building is dangerous.","intent":"Answer that even if the building is old, it isn't dangerous (use: Aunque + subjunctive).","accept":["Aunque el edificio sea viejo, no es peligroso.","Aunque sea viejo, el edificio es seguro.","No es peligroso, aunque tenga muchos años."],"require":[{"type":"subjunctiveAfter","trigger":"aunque","label":"after aunque, use the subjunctive (aunque sea, aunque tenga)"}],"focus":"g:subj-concessive","next":"t3"},{"id":"t3","npc":"Yesid: ¿Y qué pruebas tenemos?","npcEn":"Yesid: And what proof do we have?","intent":"Say that a study shows that the building has no problems (use: Un estudio muestra que).","accept":["Un estudio muestra que el edificio no tiene problemas.","Un estudio de la universidad muestra que el edificio es seguro.","Un estudio de un ingeniero muestra que la estructura es segura."],"require":[{"type":"regex","pattern":"\\bun estudio\\b[^.]*\\bmuestra que\\b","flags":"iu","label":"cite the evidence: un estudio muestra que"}],"focus":"p:un-estudio-muestra-que","next":"t4"},{"id":"t4","npc":"Yesid: Una cosa más. Altamira quiere un acuerdo antes de la audiencia. ¿Firmas?","npcEn":"Yesid: One more thing. Altamira wants a deal before the hearing. Will you sign?","intent":"Say you will sign only on condition that the café stays open (use: con tal de que + subjunctive).","accept":["Firmo con tal de que el café siga abierto.","Solo firmo con tal de que los vecinos puedan quedarse.","Con tal de que el café siga abierto, firmo."],"require":[{"type":"subjunctiveAfter","trigger":"con tal de que","label":"after con tal de que, use the subjunctive (siga, puedan)"}],"focus":"g:subj-conditions","next":"t5"},{"id":"t5","npc":"Yesid: Nos llaman ya. ¡Mucha suerte, Tomás!","npcEn":"Yesid: They're calling us now. Good luck, Tomás!","intent":"Thank him and say you're ready.","accept":["Gracias, Yesid. Estoy listo.","Muchas gracias por tu ayuda. Ya estoy listo.","Gracias por todo. Lo tengo clarísimo."],"require":[],"focus":"c:lo-tengo-clarisimo","next":null}],"r":["c:lo-tengo-clarisimo","g:gender-articles","g:present-ar","g:questions","g:ser-identity","g:subj-concessive","g:subj-conditions","p:a-mi-modo-de-ver","p:un-estudio-muestra-que"],"d":null},
{"id":"sc-u44-b","unit":"u44","band":"B2","title":"La entrevista de Mariana","brief":"You're Tomás, being interviewed by Mariana for her article on the Altamira plan. She's a friend, so use tú. Give a balanced, careful answer: agree in general, concede, say what you suspect, and push back on a doubter.","turns":[{"id":"t1","npc":"Mariana: Es para mi artículo. ¿Estás de acuerdo con el plan de Altamira?","npcEn":"Mariana: This is for my article. Do you agree with Altamira's plan?","intent":"Say that you agree with them that the neighbourhood needs investment (use: Estoy de acuerdo con ellos en que).","accept":["Sí, estoy de acuerdo con ellos en que el barrio necesita inversión.","Estoy de acuerdo con Altamira en que el barrio necesita inversión.","Claro, estoy de acuerdo con ellos en que hace falta inversión."],"require":[{"type":"regex","pattern":"\\bestoy de acuerdo con \\w+ en que\\b","flags":"iu","label":"say: estoy de acuerdo con ... en que"}],"focus":"p:estar-de-acuerdo-con-en","next":"t2"},{"id":"t2","npc":"Mariana: En los planos, el proyecto se ve precioso.","npcEn":"Mariana: On the plans, the project looks beautiful.","intent":"Say that it looks like a good idea, but it has problems (use: Aunque + indicative).","accept":["Aunque parece una buena idea, tiene problemas.","Aunque es precioso, el barrio no está en los planos.","Sí, aunque parece muy bueno, tiene un problema grande."],"require":[{"type":"regex","pattern":"\\baunque\\b","flags":"iu","label":"say: aunque"}],"focus":"g:concession-despite","next":"t3"},{"id":"t3","npc":"Mariana: ¿Y por qué dudas tanto de ellos?","npcEn":"Mariana: And why do you doubt them so much?","intent":"Say you think they are hiding something (use: Creo que + indicative).","accept":["Creo que ocultan algo.","Creo que Altamira oculta algo.","Creo que ellos ocultan la verdad sobre el edificio."],"require":[{"type":"regex","pattern":"\\bcreo que\\b","flags":"iu","label":"say: creo que"}],"focus":"g:that-clauses","next":"t4"},{"id":"t4","npc":"Mariana: ¿Crees que van a decir la verdad en la audiencia?","npcEn":"Mariana: Do you think they will tell the truth at the hearing?","intent":"Say you are not sure that they will tell the whole truth (use: No estoy seguro de que + subjunctive).","accept":["No estoy seguro de que digan toda la verdad.","No estoy seguro de que Altamira diga la verdad.","No estoy seguro de que sean sinceros."],"require":[{"type":"subjunctiveAfter","trigger":"no estoy seguro de que","label":"after no estoy seguro de que, use the subjunctive (digan, sean)"}],"focus":"x:impresion-vs-no-estoy-seguro","next":"t5"},{"id":"t5","npc":"Mariana: Un lector escribe que a nadie le importa un edificio viejo. ¿Qué le dices?","npcEn":"Mariana: A reader writes that nobody cares about an old building. What do you say to him?","intent":"Concede one point, then push back. Start with \"Puede que\", \"No dudo que\" or \"Se podría objetar que\", then add pero, sin embargo or ahora bien.","accept":["Puede que sea viejo, pero también es parte de nuestra historia.","No dudo que sea viejo. Ahora bien, vale la pena cuidarlo.","Se podría objetar que es viejo. Sin embargo, es parte del patrimonio."],"require":[{"type":"regex","pattern":"\\b(puede que|no dudo que|se podr[ií]a objetar que)\\b","flags":"iu","label":"concede first: puede que, no dudo que, se podría objetar que"},{"type":"regex","pattern":"\\b(pero|sin embargo|ahora bien)\\b","flags":"iu","label":"then turn it round: pero, sin embargo, ahora bien"}],"focus":"p:concede-pero","next":"t6"},{"id":"t6","npc":"Mariana: Perfecto, ya tengo mi cita. ¿Te invito a un tinto?","npcEn":"Mariana: Perfect, now I have my quote. Shall I buy you a tinto?","intent":"Accept and thank her.","accept":["Desde luego, gracias por escucharme.","Claro que sí, Mariana. Gracias.","Con mucho gusto, gracias."],"require":[],"focus":"c:desde-luego","next":null}],"r":["c:desde-luego","g:concession-despite","g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:that-clauses","p:concede-pero","p:estar-de-acuerdo-con-en","x:impresion-vs-no-estoy-seguro"],"d":null},
{"id":"sc-u44-c","unit":"u44","band":"B2","title":"La audiencia","brief":"You're Tomás at the public hearing, speaking to the president of the heritage institute. Use usted, never tú. Open with your position, answer the danger claim, set a condition, correct Altamira's lawyer and close with your head up.","turns":[{"id":"t1","npc":"Presidenta: Buenos días. Tiene la palabra el dueño del café. ¿Qué viene a defender?","npcEn":"President: Good morning. The owner of the café has the floor. What have you come to defend?","intent":"Open by saying you are going to defend that the building has great value for the city (use: Voy a defender que).","accept":["Voy a defender que el edificio tiene mucho valor para la ciudad.","Buenos días. Voy a defender que el café es parte del patrimonio de Bogotá.","Señora presidenta, voy a defender que este edificio tiene mucho valor."],"require":[{"type":"regex","pattern":"\\bvoy a defender que\\b","flags":"iu","label":"open with: voy a defender que"},{"type":"avoidsAny","words":["tú","eres","tienes"],"label":"use usted, not tú"}],"focus":"p:voy-a-defender-que","next":"t2"},{"id":"t2","npc":"Presidenta: Altamira dice que el edificio es inseguro. ¿Qué responde usted?","npcEn":"President: Altamira says the building is unsafe. What do you answer?","intent":"Say that even if the building needs repairs, it is not unsafe (use: Aunque + subjunctive).","accept":["Aunque el edificio necesite arreglos, no es inseguro.","Aunque necesite arreglos, el edificio tiene mucho valor.","Aunque tenga problemas, el edificio sigue siendo importante para el barrio."],"require":[{"type":"subjunctiveAfter","trigger":"aunque","label":"after aunque, use the subjunctive (necesite, tenga)"}],"focus":"g:subj-concessive","next":"t3"},{"id":"t3","npc":"Presidenta: ¿Aceptarían ustedes arreglos en el edificio?","npcEn":"President: Would you accept repairs on the building?","intent":"Say you accept repairs on condition that the neighbours can stay (use: con tal de que + subjunctive).","accept":["Aceptamos los arreglos con tal de que los vecinos puedan quedarse.","Sí, con tal de que nadie tenga que irse.","Aceptamos arreglos con tal de que no cierren el café."],"require":[{"type":"subjunctiveAfter","trigger":"con tal de que","label":"after con tal de que, use the subjunctive (puedan, tenga, cierren)"}],"focus":"g:subj-conditions","next":"t4"},{"id":"t4","npc":"Abogada de Altamira: Ese edificio no tiene ningún valor histórico.","npcEn":"Altamira's lawyer: That building has no historical value at all.","intent":"Correct her: it has more than historical value (use: No solo... sino también...).","accept":["No solo tiene valor histórico, sino también valor para los vecinos.","Eso no es cierto. No solo es antiguo, sino también parte de nuestra historia.","No solo guarda las cartas de Rosa, sino también la memoria del barrio."],"require":[{"type":"regex","pattern":"\\bno solo\\b[^.]*\\bsino\\b","flags":"iu","label":"use: no solo... sino también..."}],"focus":"g:argument-markers","next":"t5"},{"id":"t5","npc":"Presidenta: Último punto. ¿Y si pierden?","npcEn":"President: Last point. And if you lose?","intent":"Say that even if you lose, you will tell the truth today (use: Aunque + subjunctive).","accept":["Aunque perdamos, hoy decimos la verdad.","Aunque perdamos, no vamos a callar la verdad.","Aunque no ganemos, vamos a decir la verdad."],"require":[{"type":"subjunctiveAfter","trigger":"aunque","label":"after aunque, use the subjunctive (perdamos, ganemos)"}],"focus":"g:subj-concessive","next":"t6"},{"id":"t6","npc":"Presidenta: Gracias, señor. Vamos a decidir en tres meses.","npcEn":"President: Thank you, sir. We are going to decide in three months.","intent":"Thank her formally and say goodbye.","accept":["Muchas gracias, señora presidenta. Hasta pronto.","Gracias por escucharnos. Buenas tardes.","Se lo agradezco mucho. Buenas tardes."],"require":[{"type":"avoidsAny","words":["tú","eres","tienes"],"label":"use usted, not tú"}],"focus":"c:sin-duda-alguna","next":null}],"r":["c:sin-duda-alguna","g:argument-markers","g:gender-articles","g:questions","g:stem-boot","g:subj-concessive","g:subj-conditions","p:voy-a-defender-que"],"d":null},
{"id":"sc-u44-d","unit":"u44","band":"B2","title":"La noche antes","brief":"You're Tomás in the closed café the night before the hearing, talking with Don Hernando. He's older than you and courtly, so use usted. Give your opinion, make suggestions, and look back.","turns":[{"id":"t1","npc":"Hernando: Buenas noches, joven. Mañana quiero hablar en la audiencia. ¿Qué opina usted de que hable yo primero?","npcEn":"Hernando: Good evening, young man. Tomorrow I want to speak at the hearing. What do you think of me speaking first?","intent":"Say that his speaking first seems like a very good idea to you. Start with: Que...","accept":["Que hable usted primero me parece muy buena idea.","Que usted hable primero me parece lo mejor.","Que hable usted primero me parece perfecto, Don Hernando."],"require":[{"type":"regex","pattern":"^\\s*que\\b[^.]*\\bme parece\\b","flags":"iu","label":"start with Que... and end with ...me parece"},{"type":"avoidsAny","words":["hables","tú","eres"],"label":"use usted (hable usted), not tú"}],"focus":"p:que-subj-me-parece","next":"t2"},{"id":"t2","npc":"Hernando: Le pregunto con franqueza: ¿cree usted que ganamos?","npcEn":"Hernando: I ask you frankly: do you think we win?","intent":"Say you see it as difficult, but not impossible (use: Lo veo difícil).","accept":["Lo veo difícil, don Hernando, pero no imposible.","Lo veo difícil, pero vale la pena intentarlo.","Sinceramente, lo veo difícil."],"require":[{"type":"regex","pattern":"\\blo veo dif[ií]cil\\b","flags":"iu","label":"say: lo veo difícil"}],"focus":"p:lo-veo-dificil","next":"t3"},{"id":"t3","npc":"Hernando: Entonces, ¿qué hacemos antes de mañana?","npcEn":"Hernando: So what do we do before tomorrow?","intent":"Suggest what should be done tonight (use: Habría que + infinitive).","accept":["Habría que hablar con todos los vecinos esta noche.","Habría que revisar las cartas de Rosa otra vez.","Habría que llamar a Mariana para las fotos."],"require":[{"type":"regex","pattern":"\\bhabr[ií]a que\\b","flags":"iu","label":"suggest it with: habría que"}],"focus":"p:habria-que","next":"t4"},{"id":"t4","npc":"Hernando: Hay un problema. Me dijeron que los vecinos del segundo piso quieren vender.","npcEn":"Hernando: There is a problem. They told me the neighbours on the second floor want to sell.","intent":"Say it would be good if you and he talked to them tonight (use: Estaría bien que + subjunctive).","accept":["Estaría bien que habláramos con ellos hoy.","Estaría bien que usted y yo habláramos con ellos esta noche.","Estaría bien que fuéramos a hablar con ellos ahora mismo."],"require":[{"type":"subjunctiveAfter","trigger":"estaría bien que","label":"after estaría bien que, use the past subjunctive (habláramos, fuéramos)"}],"focus":"p:estaria-bien-que","next":"t5"},{"id":"t5","npc":"Hernando: Dígame, joven. Si hubiera llegado antes a Bogotá, ¿habría hecho algo distinto?","npcEn":"Hernando: Tell me, young man. If you had arrived in Bogotá earlier, would you have done something different?","intent":"Say that if you had come earlier, you would have talked more with your grandmother (use: Si hubiera... habría...).","accept":["Si hubiera llegado antes, habría hablado más con mi abuela.","Si hubiera venido antes, habría pasado más tiempo con Rosa.","Sí. Si hubiera llegado antes, habría hablado más con ella."],"require":[{"type":"regex","pattern":"\\bsi (hubiera|hubiese)\\b","flags":"iu","label":"start the condition with: si hubiera"},{"type":"regex","pattern":"\\bhabr[ií]a\\b","flags":"iu","label":"finish it with: habría"}],"focus":"g:si-past-unreal","next":"t6"},{"id":"t6","npc":"Hernando: Rosa estaría orgullosa de usted. Vamos a dormir, que mañana es largo.","npcEn":"Hernando: Rosa would be proud of you. Let's go to sleep, tomorrow is long.","intent":"Thank him warmly and say good night.","accept":["Gracias, Don Hernando. Buenas noches.","Muchas gracias. Hasta mañana, Don Hernando.","Se lo agradezco mucho, Don Hernando. Buenas noches."],"require":[{"type":"avoidsAny","words":["tú","eres","tienes"],"label":"use usted, not tú"}],"focus":"c:si-tu-lo-dices","next":null}],"r":["c:si-tu-lo-dices","g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:si-past-unreal","g:stem-boot","g:that-clauses","g:verb-infinitive","p:estaria-bien-que","p:habria-que","p:lo-veo-dificil","p:que-subj-me-parece"],"d":466,"spare":true},
{"id":"sc-u44-e","unit":"u44","band":"B2","title":"Pan de bono para la suerte","brief":"You're Tomás, up late in the kitchen with Vale, who is baking and teasing you about tomorrow. She's quick and dry, and she's your friend, so use tú. Say what you believe, concede, and practise your speech.","turns":[{"id":"t1","npc":"Vale: ¿Todavía despierto? Son las doce. Estás seguro de lo de mañana, ¿no?","npcEn":"Vale: Still awake? It's twelve. You're sure about tomorrow, right?","intent":"Say yes, you are convinced that the building has value (use: Estoy convencido de que).","accept":["Sí, estoy convencido de que el edificio tiene valor.","Claro. Estoy convencido de que tenemos razón.","Estoy convencido de que el café vale mucho para el barrio."],"require":[{"type":"regex","pattern":"\\bestoy convencido de que\\b","flags":"iu","label":"say: estoy convencido de que"}],"focus":"p:estar-convencido-de","next":"t2"},{"id":"t2","npc":"Vale: Yo no lo veo tan claro. Altamira tiene más plata y más abogados.","npcEn":"Vale: I don't see it that clearly. Altamira has more money and more lawyers.","intent":"Tell her she is completely right, but that you have something better (use: Tienes toda la razón, pero...).","accept":["Tienes toda la razón, pero tenemos algo mejor: la verdad.","Tienes toda la razón, pero la plata no lo es todo.","Tienes toda la razón. Aun así, ellos no tienen a los vecinos."],"require":[{"type":"regex","pattern":"\\btienes toda la raz[oó]n\\b","flags":"iu","label":"say: tienes toda la razón"}],"focus":"p:tienes-toda-la-razon","next":"t3"},{"id":"t3","npc":"Vale: ¿Y si perdemos? Dime la verdad.","npcEn":"Vale: And if we lose? Tell me the truth.","intent":"Say that even if you lose, it is worth trying (use: Aunque + subjunctive, and vale la pena).","accept":["Aunque perdamos, vale la pena intentarlo.","Aunque no ganemos, vale la pena luchar.","Aunque perdamos, va a valer la pena."],"require":[{"type":"subjunctiveAfter","trigger":"aunque","label":"after aunque, use the subjunctive (perdamos, ganemos)"},{"type":"regex","pattern":"\\b(vale|valer|valdr[aá])\\b[^.]*\\bla pena\\b","flags":"iu","label":"include: vale la pena"}],"focus":"g:subj-concessive","next":"t4"},{"id":"t4","npc":"Vale: Son las doce y media. ¿Practicamos tu discurso o duermes?","npcEn":"Vale: It's half past midnight. Do we practise your speech or do you sleep?","intent":"Say you would prefer that she listened to your speech once more (use: Preferiría que + subjunctive).","accept":["Preferiría que me escucharas una vez más.","Preferiría que lo practicáramos otra vez.","Preferiría que escucharas mi discurso otra vez, por favor."],"require":[{"type":"subjunctiveAfter","trigger":"preferiría que","label":"after preferiría que, use the past subjunctive (escucharas, practicáramos)"}],"focus":"p:preferiria-que","next":"t5"},{"id":"t5","npc":"Vale: Bien. A ver, dime: ¿cuál es el problema de fondo?","npcEn":"Vale: Fine. Go on, tell me: what is the underlying problem?","intent":"Say that the root of the problem is that nobody listens to the neighbours (use: La raíz del problema).","accept":["La raíz del problema es que nadie escucha a los vecinos.","Para mí, la raíz del problema es que nadie escucha al barrio.","La raíz del problema es que Altamira no escucha a nadie."],"require":[{"type":"regex","pattern":"\\bla ra[ií]z del problema\\b","flags":"iu","label":"say: la raíz del problema"}],"focus":"c:la-raiz-del-problema","next":"t6"},{"id":"t6","npc":"Vale: Con ese discurso hasta yo voto por ti. Toma, un pan de bono para la suerte.","npcEn":"Vale: With that speech even I would vote for you. Here, a pan de bono for luck.","intent":"Thank her and say good night.","accept":["Gracias, Vale. Buenas noches.","Gracias por todo, Vale. Hasta mañana.","Qué rico, gracias. Hasta mañana."],"require":[],"focus":"c:puede-que-me-equivoque","next":null}],"r":["c:la-raiz-del-problema","c:puede-que-me-equivoque","g:gender-articles","g:present-ar","g:ser-identity","g:stem-boot","g:subj-concessive","p:estar-convencido-de","p:preferiria-que","p:tienes-toda-la-razon"],"d":null,"spare":true},
{"id":"sc-u44-f","unit":"u44","band":"B2","title":"La oferta de doña Lucía","brief":"You're Tomás at the café counter. Lucía, an older neighbour from the second floor, has come to say she will accept Altamira's offer. She is older than you, so use usted. Listen, find common ground, and give her reasons to stay.","turns":[{"id":"t1","npc":"Lucía: Tomás, buenos días. Vengo a decirte que voy a aceptar la oferta de Altamira.","npcEn":"Lucía: Tomás, good morning. I've come to tell you that I'm going to accept Altamira's offer.","intent":"Greet her politely and ask why she wants to accept (use usted).","accept":["Buenos días, doña Lucía. ¿Por qué quiere vender?","Buenos días, doña Lucía. ¿Me puede explicar por qué?","Buenos días. ¿Por qué quiere aceptar la oferta, doña Lucía?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsAny","words":["quieres","puedes","tú"],"label":"use usted, not tú"}],"focus":"g:subj-conditions","next":"t2"},{"id":"t2","npc":"Lucía: Porque ofrecen mucha plata, y yo ya no tengo edad para pelear.","npcEn":"Lucía: Because they offer a lot of money, and I'm too old to fight.","intent":"Say you share her point of view, but add that you see it differently (use: Comparto su punto de vista).","accept":["Comparto su punto de vista, pero la plata se acaba.","Comparto su punto de vista: la plata ayuda. Pero esta casa también es suya.","Comparto su punto de vista, doña Lucía, pero yo lo veo distinto."],"require":[{"type":"regex","pattern":"\\bcomparto su punto de vista\\b","flags":"iu","label":"say: comparto su punto de vista"}],"focus":"p:comparto-su-punto-de-vista","next":"t3"},{"id":"t3","npc":"Lucía: ¿Y qué voy a hacer si me quedo y cierran la calle?","npcEn":"Lucía: And what am I going to do if I stay and they close the street?","intent":"Promise help in case they close the street (use: En caso de que + subjunctive).","accept":["En caso de que cierren la calle, yo la ayudo.","En caso de que cierren la calle, la vamos a ayudar todos.","La ayudamos en caso de que cierren la calle."],"require":[{"type":"subjunctiveAfter","trigger":"en caso de que","label":"after en caso de que, use the subjunctive (cierren)"}],"focus":"g:subj-conditions","next":"t4"},{"id":"t4","npc":"Lucía: No me entiendes. A mi edad, solo quiero tranquilidad.","npcEn":"Lucía: You don't understand me. At my age, I only want peace and quiet.","intent":"Say that for you it is essential that the building stays the neighbourhood's (use: Es imprescindible que...).","accept":["Es imprescindible que el edificio siga siendo del barrio.","Para mí, es imprescindible que los vecinos se queden aquí.","Entiendo, pero es imprescindible que ustedes sigan aquí."],"require":[{"type":"regex","pattern":"\\bes imprescindible que\\b","flags":"iu","label":"say: es imprescindible que"}],"focus":"p:imprescindible","next":"t5"},{"id":"t5","npc":"Lucía: ¿Y yo qué gano si me quedo?","npcEn":"Lucía: And what do I gain if I stay?","intent":"Say that in the long term the neighbourhood is worth more than the money (use: A largo plazo).","accept":["A largo plazo, el barrio vale más que la oferta.","A largo plazo, usted gana más quedándose aquí.","A largo plazo, la plata se acaba y el barrio sigue."],"require":[{"type":"regex","pattern":"\\ba largo plazo\\b","flags":"iu","label":"say: a largo plazo"}],"focus":"c:a-largo-plazo","next":"t6"},{"id":"t6","npc":"Lucía: Está bien, me quedo. ¿Me das un tinto?","npcEn":"Lucía: All right, I'm staying. Will you give me a tinto?","intent":"Say of course, this tinto is on the house.","accept":["Claro que sí. Este tinto es de la casa.","Con mucho gusto, doña Lucía. El tinto va por la casa.","Claro, doña Lucía. Hoy el tinto es mío."],"require":[],"focus":"c:pues-si","next":null}],"r":["c:a-largo-plazo","c:pues-si","g:gender-articles","g:ir-a-plans","g:present-ar","g:questions","g:reflexive-routine","g:si-present","g:stem-boot","g:subj-conditions","g:yo-irregular","p:comparto-su-punto-de-vista","p:imprescindible"],"d":null,"spare":true},
{"id":"sc-u45-a","unit":"u45","band":"B2","title":"Sin contestar","brief":"You're helping Mariana at a café table while she writes her follow-up story about Altamira and Rengifo, the suspended official. She's a friend, so use tú. Guess, report carefully what is only alleged, give a number, and admit what you don't know.","turns":[{"id":"t1","npc":"Mariana: Rengifo lleva dos días sin contestar el teléfono. ¿Dónde estará?","npcEn":"Mariana: Rengifo hasn't answered his phone for two days. Where could he be?","intent":"Guess where he is: he has probably left the country (use the future perfect: se habrá ido).","accept":["Se habrá ido del país.","Ya se habrá ido de Bogotá.","Habrá salido de viaje, ¿no?"],"require":[{"type":"regex","pattern":"\\bhabrá(n)?\\s+\\w*(ado|ido|to|cho)\\b","flags":"iu","label":"guess with the future perfect: se habrá ido, habrá salido"}],"focus":"g:future-perfect","next":"t2"},{"id":"t2","npc":"Mariana: Mi fuente dice que Altamira le pagó a Rengifo, pero no puedo escribirlo como un hecho. ¿Cómo lo digo?","npcEn":"Mariana: My source says Altamira paid Rengifo, but I can't write it as a fact. How do I put it?","intent":"Tell her to write that Altamira allegedly paid Rengifo (use the conditional: habría pagado).","accept":["Escribe que Altamira le habría pagado a Rengifo.","Según una fuente, Altamira le habría pagado a Rengifo.","Altamira le habría pagado a Rengifo, según tu fuente."],"require":[{"type":"regex","pattern":"\\bhabría(n)?\\s+\\w*(ado|ido|to|cho)\\b","flags":"iu","label":"for what is only alleged, use the conditional: habría pagado"}],"focus":"g:conditional-rumour","next":"t3"},{"id":"t3","npc":"Mariana: Perfecto. Y en el periódico dicen que los arriendos del barrio subieron mucho. ¿Cuánto?","npcEn":"Mariana: Perfect. And the newspaper says that rents in the neighbourhood went up a lot. By how much?","intent":"Say that rents doubled in five years (use se duplicaron).","accept":["Se duplicaron en cinco años.","Los arriendos se duplicaron en solo cinco años.","En cinco años, los arriendos se duplicaron."],"require":[{"type":"regex","pattern":"\\bse duplicar(on|á)\\b","flags":"iu","label":"say they doubled: se duplicaron"}],"focus":"p:duplicarse","next":"t4"},{"id":"t4","npc":"Mariana: En las redes dicen que Rengifo ya está en Miami. ¿Tú qué crees? ¿Será verdad?","npcEn":"Mariana: On social media they say Rengifo is already in Miami. What do you think? Could it be true?","intent":"Say you don't know (use: Quién sabe, No tengo ni idea or Habría que ver si).","accept":["Quién sabe.","No tengo ni idea de dónde está.","Habría que ver si es verdad."],"require":[{"type":"regex","pattern":"\\b(quién sabe|no tengo ni idea|habría que ver si)\\b","flags":"iu","label":"admit what you don't know: quién sabe, no tengo ni idea"}],"focus":"c:quien-sabe","next":"t5"},{"id":"t5","npc":"Mariana: Gracias por la ayuda. ¿Te invito a un tinto?","npcEn":"Mariana: Thanks for the help. Shall I buy you a coffee?","intent":"Accept and thank her.","accept":["Claro, gracias.","Con mucho gusto, gracias.","Sí, por favor. Muchas gracias."],"require":[],"focus":"c:quien-sabe","next":null}],"r":["c:quien-sabe","g:conditional-rumour","g:estar-location-states","g:future-conjecture","g:future-perfect","g:gender-articles","g:present-ar","g:questions","g:stem-e-i","g:that-clauses","p:duplicarse"],"d":null},
{"id":"sc-u45-b","unit":"u45","band":"B2","title":"El hotel de al lado","brief":"Don Hernando shows you a newspaper article at the café. He is older than you, so use usted. Ask whether a claim is true, say what people are saying, say who told you, and set a condition for staying.","turns":[{"id":"t1","npc":"Hernando: Joven, mire esto en el periódico. Dice que el hotel de Altamira estará listo antes de la decisión.","npcEn":"Hernando: Young man, look at this in the newspaper. It says Altamira's hotel will be ready before the decision.","intent":"Ask whether it is true that the hotel will be ready before the decision (use: ¿Es verdad que…?).","accept":["¿Es verdad que el hotel estará listo antes de la decisión?","Don Hernando, ¿es verdad que terminarán el hotel antes de la decisión?","¿Es cierto que el hotel estará listo tan pronto?"],"require":[{"type":"regex","pattern":"\\bes (verdad|cierto) que\\b","flags":"iu","label":"check the claim: ¿es verdad que…?"},{"type":"question"}],"focus":"p:es-verdad-eso-de-que","next":"t2"},{"id":"t2","npc":"Hernando: Eso dice el comunicado de la empresa. ¿Y qué se dice en el barrio?","npcEn":"Hernando: That is what the company's statement says. And what is being said in the neighbourhood?","intent":"Say what people in the neighbourhood are saying about the hotel (use the impersonal se: se dice que, se cree que).","accept":["Se dice que el hotel no estará listo a tiempo.","Se cree que es un truco de Altamira.","En el barrio se dice que la obra va muy lenta."],"require":[{"type":"regex","pattern":"\\bse (dice|cree|cuenta|piensa|habla)\\b","flags":"iu","label":"use the impersonal se: se dice que, se cree que"}],"focus":"g:impersonal-register","next":"t3"},{"id":"t3","npc":"Hernando: ¿Y usted cómo lo sabe?","npcEn":"Hernando: And how do you know?","intent":"Say that someone told you the building work is going badly (use: Me contó un… que).","accept":["Me contó un obrero que llevan una semana sin cemento.","Un vecino me contó que la obra va muy lenta.","Me contó un amigo que casi no hay obreros en la obra."],"require":[{"type":"regex","pattern":"\\bme cont[oó] .*\\bque\\b|\\bcont[oó] que\\b","flags":"iu","label":"say who told you: me contó… que…"}],"focus":"p:me-contaron-que","next":"t4"},{"id":"t4","npc":"Hernando: Entonces Altamira promete demasiado. ¿Y nosotros qué hacemos mientras tanto?","npcEn":"Hernando: So Altamira is promising too much. And what do we do in the meantime?","intent":"Say you stay open as long as there is no decision (use: Mientras no + subjunctive).","accept":["Mientras la ciudad no decida, nos quedamos aquí.","Mientras la ciudad no decida, el café sigue abierto.","Seguimos abiertos mientras el alcalde no responda."],"require":[{"type":"subjunctiveAfter","trigger":"mientras","label":"after mientras no, use the subjunctive: mientras no haya"}],"focus":"x:mientras-ind-subj","next":"t5"},{"id":"t5","npc":"Hernando: Así me gusta. Le invito un tinto, joven.","npcEn":"Hernando: That's the spirit. Let me buy you a coffee, young man.","intent":"Thank him politely and say goodbye until tomorrow (he is older, so use usted).","accept":["Muchas gracias, don Hernando. Hasta mañana.","Se lo agradezco mucho, don Hernando.","Gracias, con gusto. Hasta mañana."],"require":[{"type":"avoidsAny","words":["tú","gracias a ti","contigo"],"label":"use usted with Don Hernando"}],"focus":"g:impersonal-register","next":null}],"r":["g:gender-articles","g:impersonal-register","g:present-er-ir","g:questions","g:stem-e-i","p:es-verdad-eso-de-que","p:me-contaron-que","x:mientras-ind-subj"],"d":null},
{"id":"sc-u45-c","unit":"u45","band":"B2","title":"Una llamada de la emisora","brief":"Camila, an editor at the radio station, calls you for background on the Rengifo story. She doesn't know you, so use usted. Say how well you follow the case, report what is only alleged, give an approximate number and predict what Altamira will say.","turns":[{"id":"t1","npc":"Camila: Buenas tardes, soy Camila, de la emisora. Mariana dice que usted conoce el caso Rengifo. ¿Está al tanto de todo?","npcEn":"Camila: Good afternoon, this is Camila from the radio station. Mariana says you know the Rengifo case. Are you up to date on everything?","intent":"Say you are up to date on what the newspaper says (use: estoy al tanto de).","accept":["Sí, estoy al tanto de lo que dice el periódico.","Estoy al tanto de todo, sí. Leo todo lo que sale.","Más o menos. Estoy al tanto de lo básico."],"require":[{"type":"regex","pattern":"\\bal tanto de\\b","flags":"iu","label":"say you are informed: estoy al tanto de…"}],"focus":"p:estar-al-tanto-de","next":"t2"},{"id":"t2","npc":"Camila: Entonces dígame una cosa: ¿Rengifo sí salió del país?","npcEn":"Camila: Then tell me something: did Rengifo really leave the country?","intent":"Answer carefully: according to the paper, he reportedly left (use the conditional: habría salido).","accept":["Según el periódico, Rengifo habría salido del país.","Según los vecinos, Rengifo habría salido del país, pero nadie lo confirma.","Rengifo habría salido del país, según una fuente."],"require":[{"type":"regex","pattern":"\\bhabría(n)?\\s+\\w*(ado|ido|to|cho)\\b","flags":"iu","label":"for what is only reported, use the conditional: habría salido"}],"focus":"g:conditional-rumour","next":"t3"},{"id":"t3","npc":"Camila: Hay una carta de protesta. ¿Cuánta gente la firmó?","npcEn":"Camila: There is a protest letter. How many people signed it?","intent":"Say about a thousand people (use an approximation: cerca de, unas, más o menos).","accept":["Cerca de mil personas la firmaron.","Más o menos mil personas, creo.","Unas mil personas, según los vecinos."],"require":[{"type":"regex","pattern":"\\b(cerca de|alrededor de|en torno a|más o menos|unas?|casi)\\b","flags":"iu","label":"approximate the number: cerca de mil, unas mil"}],"focus":"p:aproximar-cifras","next":"t4"},{"id":"t4","npc":"Camila: Altamira lo niega todo. ¿Cree usted que dirá la verdad?","npcEn":"Camila: Altamira denies everything. Do you think it will tell the truth?","intent":"Say it most likely won't tell the whole truth (use: Lo más probable es que + subjunctive).","accept":["Lo más probable es que no diga toda la verdad.","Lo más probable es que no diga nada nuevo.","No tengo ni idea, pero lo más probable es que no."],"require":[{"type":"regex","pattern":"\\blo más probable es que\\b","flags":"iu","label":"use: lo más probable es que…"}],"focus":"p:lo-mas-probable-es-que","next":"t5"},{"id":"t5","npc":"Camila: Muchas gracias por su tiempo. Mañana lo llamo para grabar.","npcEn":"Camila: Thank you very much for your time. Tomorrow I'll call you to record.","intent":"Thank her and say goodbye until tomorrow (she is a stranger, so use usted).","accept":["Gracias a usted. Hasta mañana.","Muchas gracias a usted, Camila. Hasta mañana.","Con mucho gusto. Hasta pronto."],"require":[{"type":"avoidsAny","words":["tú","gracias a ti","contigo"],"label":"use usted with Camila"}],"focus":"g:impersonal-register","next":null}],"r":["g:conditional-rumour","g:direct-objects","g:gender-articles","g:impersonal-register","g:present-er-ir","g:that-clauses","p:aproximar-cifras","p:estar-al-tanto-de","p:lo-mas-probable-es-que"],"d":null,"spare":true},
{"id":"sc-u46-a","unit":"u46","band":"B2","title":"Palabra por palabra","brief":"You're on the phone with Tomás's lawyer, Dr Uribe. She is formal, so use usted. She wants the whole conversation with Yesid reported accurately: who said what, and what you can only repeat without vouching for it.","turns":[{"id":"t1","npc":"Uribe: Hola, Tomás. Necesito que me cuente exactamente qué le dijo Yesid sobre la oferta de Altamira.","npcEn":"Uribe: Hello, Tomás. I need you to tell me exactly what Yesid told you about Altamira's offer.","intent":"Report that Yesid told you Altamira had offered him much more than his share was worth.","accept":["Me dijo que Altamira le había ofrecido mucho más de lo que valía su parte.","Yesid me contó que Altamira le ofreció mucho más por su parte.","Me explicó que Altamira le había ofrecido bastante más de lo que valía su parte."],"require":[{"type":"regex","pattern":"\\b(dijo|cont(ó|aron)|explicó|aseguró)\\s+que\\b","flags":"iu","label":"report it with dijo que, contó que, explicó que"}],"focus":"g:reported-speech-full","next":"t2"},{"id":"t2","npc":"Uribe: ¿Y le pidieron algo a cambio?","npcEn":"Uribe: And did they ask him for anything in return?","intent":"Say that, according to Yesid, they asked him to keep quiet, and told him the café would close anyway.","accept":["Me dijo que le pidieron que no dijera nada, y que el café iba a cerrar igual.","Asegura que le pidieron que guardara el secreto y que el café cerraría igual.","Cuenta que le pidieron que lo mantuviera en secreto y que el café iba a cerrar igual."],"require":[{"type":"regex","pattern":"\\bpidi(ó|eron)\\s+que\\s+(\\w+\\s+){0,2}?\\w*(ara|era|iera|ase|ese|iese)(?!\\p{L})","flags":"iu","label":"after pidieron que, use the -ra form: dijera, guardara"}],"focus":"g:reporting-verbs-mood","next":"t3"},{"id":"t3","npc":"Uribe: Entiendo. ¿Y usted le cree?","npcEn":"Uribe: I see. And do you believe him?","intent":"Keep your distance: say that, according to him, he turned the offer down, but you can't confirm it.","accept":["Según dice, rechazó la oferta, pero yo no puedo confirmarlo.","Asegura que dijo que no, aunque no tengo cómo comprobarlo.","Él afirma que rechazó la oferta, pero no puedo confirmar nada."],"require":[{"type":"regex","pattern":"\\b(según (dice|dicen|él)|asegura|sostiene|afirma|alega)\\b","flags":"iu","label":"distance yourself: según dice, asegura que, sostiene que"},{"type":"negation","label":"say what you cannot confirm"}],"focus":"p:reporting-verbs-stance","next":"t4"},{"id":"t4","npc":"Uribe: Perdone, ¿quiere decir que usted estuvo en esa reunión con Altamira?","npcEn":"Uribe: Excuse me, do you mean you were at that meeting with Altamira?","intent":"Correct her: you were not there, you only know what Vale and Yesid told you.","accept":["No, yo no estuve allí. Solo sé lo que me contaron Vale y Yesid.","No, no asistí a esa reunión. Solo repito lo que me dijeron.","Para nada, yo no fui. Solo sé lo que me dijo Yesid."],"require":[{"type":"negation","label":"start by denying it: no, yo no estuve"}],"focus":"p:quieres-decir-que","next":"t5"},{"id":"t5","npc":"Uribe: Bien. Antes de que se me olvide, ¿puede mandarme por escrito lo que le contó Yesid?","npcEn":"Uribe: Good. Before I forget, can you send me in writing what Yesid told you?","intent":"Say yes, you will write down what Yesid said and send it tomorrow, and thank her.","accept":["Sí, le escribo todo lo que dijo Yesid y se lo mando mañana. Gracias.","Claro. Mañana le envío por escrito lo que me contó. Muchas gracias.","Con gusto, le mando mañana lo que dijo Yesid, palabra por palabra. Gracias."],"require":[{"type":"regex","pattern":"\\b(dijo|dijeron|contaron|cont(ó|aron))(?!\\p{L})","flags":"iu","label":"include what Yesid said or told you"}],"focus":"c:antes-de-que-se-me-olvide","next":null}],"r":["c:antes-de-que-se-me-olvide","g:indirect-objects","g:preterite-irregular-strong","g:reported-speech-full","g:reporting-verbs-mood","g:stem-boot","g:that-clauses","g:verb-infinitive","p:quieres-decir-que","p:reporting-verbs-stance"],"d":463},
{"id":"sc-u46-b","unit":"u46","band":"B2","title":"Lo que no se dijo","brief":"Yesid has come to the café after Vale confronted him. He is your friend, so use tú. Find out what he admits, what he denies, and what you did or did not notice, without sounding like a judge.","turns":[{"id":"t1","npc":"Yesid: Si vienes a gritarme como Vale, mejor me voy. ¿Qué te dijo ella de mí?","npcEn":"Yesid: If you've come to shout at me like Vale, I'd better go. What did she tell you about me?","intent":"Tell him Vale said that you had met with Altamira.","accept":["Vale me dijo que te habías reunido con Altamira.","Me contó que te viste con Altamira a escondidas.","Vale dice que estuviste reunido con la gente de Altamira."],"require":[{"type":"regex","pattern":"\\b(dijo|contó|dice|cuenta)\\s+que\\b","flags":"iu","label":"report it with dijo que, contó que, dice que"}],"focus":"g:reported-speech-full","next":"t2"},{"id":"t2","npc":"Yesid: Sí, me reuní con ellos. Pero fui solo a escuchar.","npcEn":"Yesid: Yes, I met with them. But I went only to listen.","intent":"Ask him straight out whether he denies that he accepted their money (use negar).","accept":["¿Niegas que aceptaras su dinero?","Entonces, ¿niegas que aceptaras la plata de Altamira?","¿Niegas que aceptaras su plata?"],"require":[{"type":"question"},{"type":"regex","pattern":"\\b(niegas|negar|negarás)\\b","flags":"iu","label":"ask with negar: ¿niegas…?"}],"focus":"p:negar-confesar","next":"t3"},{"id":"t3","npc":"Yesid: No niego que me ofrecieran mucha plata. Pero niego que yo aceptara. Y no recuerdo que me pidieran firmar nada.","npcEn":"Yesid: I don't deny that they offered me a lot of money. But I do deny that I accepted. And I don't remember them asking me to sign anything.","intent":"Tell him you don't remember him ever mentioning that meeting to you (no recuerdo que + subjunctive).","accept":["No recuerdo que me hablaras de esa reunión.","No me acuerdo de que me dijeras nada sobre eso.","Pues yo no recuerdo que me contaras que te ibas a reunir con ellos."],"require":[{"type":"regex","pattern":"\\bno (recuerdo|me acuerdo)( de)? que\\b.*\\b\\w+(aras|eras|ieras)\\b","flags":"iu","label":"no recuerdo que + the -ra form: hablaras, dijeras"}],"focus":"p:no-recuerdo-que-subj","next":"t4"},{"id":"t4","npc":"Yesid: Es que me pidieron que no hablara con nadie. Vale cree que escondo algo. ¿Tú también lo piensas?","npcEn":"Yesid: It's just that they asked me not to talk to anyone. Vale thinks I'm hiding something. Do you think so too?","intent":"Say you didn't notice him hiding anything (no noté que + subjunctive).","accept":["No noté que escondieras nada, la verdad.","Yo no noté que me escondieras nada.","La verdad, no vi que escondieras nada."],"require":[{"type":"regex","pattern":"\\bno (noté|vi|oí|escuché|percibí)(?!\\p{L}).*\\w+(aras|eras|ieras)(?!\\p{L})","flags":"iu","label":"no noté que + the -ra form: escondieras"}],"focus":"g:subj-perception-negated","next":"t5"},{"id":"t5","npc":"Yesid: Gracias por escucharme. ¿Me haces un favor? No hablemos de eso con Vale hasta que yo mismo se lo explique.","npcEn":"Yesid: Thanks for listening to me. Will you do me a favour? Let's not talk about that with Vale until I explain it to her myself.","intent":"Agree to wait, and offer him a coffee.","accept":["Está bien, esperaré. ¿Te sirvo un café?","De acuerdo, no le digo nada. Ven, te invito un tinto.","Claro, tienes mi palabra. Siéntate y te preparo un café."],"require":[],"focus":"c:no-hablemos-de-eso","next":null}],"r":["c:no-hablemos-de-eso","g:imperfect-subj","g:negation-words","g:object-pronoun-position","g:prep-pronouns","g:reported-speech-full","g:stem-boot","g:subj-past-triggers","g:subj-perception-negated","g:that-clauses","p:negar-confesar","p:no-recuerdo-que-subj"],"d":412},
{"id":"sc-u46-c","unit":"u46","band":"B2","title":"Lo dicen en la plaza","brief":"Don Hernando has come in for his morning tinto, bringing the gossip of the plaza. He is older than you and courtly, so use usted. Repeat what you have heard without vouching for it, and say what you told Yesid.","turns":[{"id":"t1","npc":"Hernando: Buenos días, joven. Antes de que se me olvide: en la plaza dicen que Yesid ya vendió su parte. ¿Qué sabe usted?","npcEn":"Hernando: Good morning, young man. Before I forget: in the plaza they say that Yesid has already sold his share. What do you know?","intent":"Say you heard that too, but Yesid claims he sold nothing.","accept":["Yo también lo oí, pero Yesid dice que no vendió nada.","Sí, me lo contaron, pero él asegura que no ha vendido nada.","Eso dicen, don Hernando, pero Yesid asegura que no vendió su parte."],"require":[{"type":"regex","pattern":"\\b(dice|dijo|asegura|niega|sostiene|afirma)\\b","flags":"iu","label":"say what Yesid claims: dice que, asegura que"},{"type":"avoidsPerson","person":"tú","label":"use usted with don Hernando"}],"focus":"p:reporting-verbs-stance","next":"t2"},{"id":"t2","npc":"Hernando: En mis tiempos, un hombre que daba su palabra no necesitaba abogados. ¿Usted qué le dijo cuando él le contó todo?","npcEn":"Hernando: In my day, a man who gave his word didn't need lawyers. What did you say to him when he told you everything?","intent":"Tell him what you said to Yesid: that you needed him to repeat it all in front of the lawyer.","accept":["Le dije que necesitaba que lo repitiera todo delante de la abogada.","Le dije que me lo explicara todo otra vez delante de la abogada.","Le dije que tenía que contárselo todo a la abogada."],"require":[{"type":"regex","pattern":"\\bdije\\s+que\\b","flags":"iu","label":"report your words with le dije que"}],"focus":"g:reporting-verbs-mood","next":"t3"},{"id":"t3","npc":"Hernando: Ya veo. Por cierto, ¿sabe que don Eusebio asistió a la asamblea y que, según dicen, votó a favor de Altamira?","npcEn":"Hernando: I see. By the way, do you know that don Eusebio attended the assembly and that, so they say, he voted in favour of Altamira?","intent":"Say you didn't know, and ask who is saying that.","accept":["No lo sabía. ¿Quién dice eso?","No tenía idea. ¿Y eso quién lo dice?","No lo sabía, don Hernando. ¿Y quién se lo contó a usted?"],"require":[{"type":"negation","label":"say you did not know"},{"type":"question","label":"ask who says so"}],"focus":"p:segun-dicen","next":"t4"},{"id":"t4","npc":"Hernando: No me malentienda, yo solo repito lo que dicen, no lo afirmo. ¿Me entiende?","npcEn":"Hernando: Don't misunderstand me, I'm only repeating what people say, I'm not claiming it. Do you understand me?","intent":"Agree, and explain with \"it's not that… but that…\": it's not that you don't believe him, but that you want proof.","accept":["Tiene razón. No es que no le crea, sino que quiero pruebas.","Claro, don Hernando. No es que dude de usted, sino que prefiero confirmarlo.","Sí, entiendo. No es que no le crea; es que necesito pruebas."],"require":[{"type":"regex","pattern":"\\bno es que\\b.*\\b(sino que|es que)\\b","flags":"iu","label":"use no es que… sino que… (or es que…)"}],"focus":"p:no-es-que-sino-que","next":"t5"},{"id":"t5","npc":"Hernando: Así me gusta, joven. Y ahora, ¿en qué íbamos? Ah, sí, mi tinto.","npcEn":"Hernando: That's what I like, young man. And now, where were we? Ah, yes, my tinto.","intent":"Say you will bring his coffee right away, and thank him for his advice (usted).","accept":["Enseguida se lo traigo, don Hernando. Gracias por el consejo.","Ya mismo le sirvo su tinto. Muchas gracias por sus palabras.","Con gusto. Le traigo el tinto, y gracias por escucharme."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted with don Hernando"}],"focus":"c:en-que-ibamos","next":null}],"r":["c:en-que-ibamos","g:gender-articles","g:present-er-ir","g:preterite-ar","g:preterite-er-ir","g:questions","g:reporting-verbs-mood","g:stem-e-i","g:that-clauses","p:no-es-que-sino-que","p:reporting-verbs-stance","p:segun-dicen"],"d":416,"spare":true},
{"id":"sc-u47-a","unit":"u47","band":"B2","title":"Quién mantuvo viva la esquina","brief":"You're Tomás, sitting in front of Mariana's microphone in the empty café. She is a friend, so use tú. Put the weight of each answer exactly where you want it: on Rosa, on the neighbours, on what you prefer.","turns":[{"id":"t1","npc":"Mariana: Estamos grabando. Para empezar: ¿quién mantuvo viva esta esquina todos estos años?","npcEn":"Mariana: We're recording. To start: who kept this corner alive all these years?","intent":"Say that it was your grandmother Rosa who kept it alive (fue ... quien ...).","accept":["Fue mi abuela Rosa quien mantuvo viva la esquina.","Quien la mantuvo viva fue Rosa, mi abuela.","Fue Rosa, mi abuela, quien mantuvo viva esta esquina.","Fue mi abuela la que mantuvo viva la esquina."],"require":[{"type":"regex","pattern":"\\bfue\\b.*\\b(quien|la que|el que)\\b|\\b(quien|la que)\\b.*\\bfue\\b","flags":"iu","label":"put the weight on Rosa with fue ... quien"}],"focus":"g:cleft-focus","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y hoy? ¿Quiénes están peleando por ella?","npcEn":"Mariana: And today? Who is fighting for it?","intent":"Say that it is the neighbours who are fighting for it (son ... quienes ...).","accept":["Son los vecinos quienes pelean por ella.","Los que pelean por ella son los vecinos del barrio.","Son los vecinos quienes la defienden, nadie más."],"require":[{"type":"regex","pattern":"\\b(son|es)\\b.*\\b(quienes|quien|los que)\\b|\\b(quienes|los que)\\b.*\\bson\\b","flags":"iu","label":"put the weight on the neighbours"}],"focus":"g:cleft-focus","next":"t3"},{"id":"t3","npc":"Mariana: Altamira dice que el agujero de la cocina ya estaba ahí. ¿Quién lo hizo?","npcEn":"Mariana: Altamira says the hole in the kitchen was already there. Who made it?","intent":"Start with the hole and say the building work next door made it (El agujero lo hizo ...).","accept":["El agujero lo hizo la máquina de la obra.","El agujero lo hicieron sus máquinas, no el tiempo.","Ese agujero lo hizo la obra de al lado, hace una semana."],"require":[{"type":"regex","pattern":"\\b(el|ese) agujero,? lo\\b","flags":"iu","label":"start with the hole, then lo"}],"focus":"g:topic-fronting","next":"t4"},{"id":"t4","npc":"Mariana: Veo que el tema de Altamira te aburre. ¿Qué prefieres que digan los oyentes?","npcEn":"Mariana: I can see the Altamira subject bores you. What would you rather the listeners say?","intent":"Say you would rather they talk about the café than about Altamira (prefiero que ... a que ...).","accept":["Prefiero que hablen del café a que hablen de Altamira.","Prefiero que los oyentes hablen de Rosa a que hablen de Altamira.","Prefiero que me pregunten por Rosa a que me pregunten por el dinero."],"require":[{"type":"regex","pattern":"\\bprefiero que\\b.*\\ba que\\b","flags":"iu","label":"use prefiero que ... a que ..."}],"focus":"p:prefiero-que-a-que","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto, ya tenemos el episodio. Gracias por tu tiempo, Tomás.","npcEn":"Mariana: Perfect, we have the episode. Thanks for your time, Tomás.","intent":"Thank her and say it bores you that everybody only talks about money (me aburre que ...).","accept":["Gracias a ti. Y me aburre que todos hablen solo de plata.","Gracias, Mariana. Me aburre que siempre hablen del dinero y no de la gente.","A ti, por venir. Me aburre que el tema sea siempre Altamira."],"require":[{"type":"regex","pattern":"\\bme aburre que\\b","flags":"iu","label":"use me aburre que"}],"focus":"p:me-aburre-que","next":null}],"r":["g:cleft-focus","g:estar-gerund","g:estar-location-states","g:gender-articles","g:questions","g:that-clauses","g:topic-fronting","p:me-aburre-que","p:prefiero-que-a-que"],"d":423},
{"id":"sc-u47-b","unit":"u47","band":"B2","title":"El loro más famoso","brief":"You're Tomás. Don Hernando, the retired taxi driver, has just heard the podcast and comes in for his coffee. He's much older than you, so use usted; he uses usted with you too. Talk about how the parrot became famous.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Anoche escuché el pódcast completo.","npcEn":"Hernando: Good morning, Tomás. Last night I listened to the whole podcast.","intent":"Greet him respectfully (usted) and ask whether he liked it.","accept":["Buenos días, don Hernando. ¿Le gustó el pódcast?","Don Hernando, buenos días. ¿Qué le pareció el episodio?","Buenas, don Hernando. ¿Lo escuchó entero? ¿Le gustó?"],"require":[{"type":"regex","pattern":"\\ble (gustó|pareció)","flags":"iu","label":"ask if he liked it, with usted"},{"type":"avoidsAny","words":["te gustó","te pareció"],"label":"use usted (le), not tú (te)"}],"focus":"g:cleft-focus","next":"t2"},{"id":"t2","npc":"Hernando: Me gustó muchísimo. Rosa estaría orgullosa de usted.","npcEn":"Hernando: I liked it enormously. Rosa would be proud of you.","intent":"Say he doesn't know how happy that makes you (No sabe lo ... que ...).","accept":["No sabe lo contento que estoy de oírlo.","Gracias, don Hernando. No sabe lo feliz que me hace eso.","No sabe lo importante que es para mí su opinión."],"require":[{"type":"regex","pattern":"\\blo (?!que\\b)[a-záéíóúñ]+ que\\b","flags":"iu","label":"use lo + adjective + que"}],"focus":"g:lo-que-intensity","next":"t3"},{"id":"t3","npc":"Hernando: Y el loro, ¿qué? Hasta los taxistas me preguntan por Simón.","npcEn":"Hernando: And the parrot? Even the taxi drivers ask me about Simón.","intent":"Say everybody knows Simón now: put Simón first (A Simón lo ...).","accept":["A Simón ya lo conocen en todo el país.","Al loro lo reconocen hasta en la calle.","A Simón lo saludan los clientes como a una estrella."],"require":[{"type":"regex","pattern":"\\b(simón|loro)\\s+(ya\\s+|todos\\s+)?(lo|los|le|les)\\b","flags":"iu","label":"start with Simón, then lo"}],"focus":"g:topic-fronting","next":"t4"},{"id":"t4","npc":"Hernando: ¿Y él? ¿Sabe que es famoso?","npcEn":"Hernando: And him? Does he know he's famous?","intent":"Joke that he has no idea and is just as calm as always (use an intensifier like súper, totalmente, realmente).","accept":["No tiene ni idea. Está súper tranquilo, come y duerme como siempre.","Simón no sabe nada, y está totalmente igual que antes.","Qué va, está realmente feliz con su fruta de todos los días."],"require":[{"type":"regex","pattern":"\\b(súper|super|totalmente|realmente|demasiado|muy)\\b","flags":"iu","label":"add an intensifier"}],"focus":"p:intensificadores","next":"t5"},{"id":"t5","npc":"Hernando: Bueno, joven, voy a tomarme un tinto antes de que esto se llene.","npcEn":"Hernando: Well, young man, I'm going to have a black coffee before this place fills up.","intent":"Say of course, and that today the house is paying (la casa invita).","accept":["Claro que sí, don Hernando. Hoy la casa invita.","Con mucho gusto. Hoy invita la casa, y el tinto está recién hecho.","Por supuesto. Hoy el tinto lo invita la casa."],"require":[{"type":"regex","pattern":"\\binvita\\b","flags":"iu","label":"say the house is paying"}],"focus":"g:topic-fronting","next":null}],"r":["g:cleft-focus","g:gender-articles","g:lo-que-intensity","g:present-ar","g:preterite-ar","g:topic-fronting","p:intensificadores"],"d":null},
{"id":"sc-u47-c","unit":"u47","band":"B2","title":"Una llamada de la radio","brief":"You're Tomás, taking a call from a radio producer you've never met. Use usted with him. He wants you live on air, and you have to say what matters to you and what day works.","turns":[{"id":"t1","npc":"Camilo: Buenas tardes, habla Camilo, de Radio Capital. ¿Hablo con el dueño del café?","npcEn":"Camilo: Good afternoon, this is Camilo from Radio Capital. Am I speaking with the owner of the café?","intent":"Say yes, it's you, and ask politely why he's calling (usted).","accept":["Sí, con él habla. ¿Cuál es el motivo de su llamada?","Sí, soy yo. ¿Para qué me llama?","Con él habla. ¿En qué puedo ayudarle?"],"require":[{"type":"regex","pattern":"\\bmotivo\\b|\\bme llama\\b|\\bayudarle\\b","flags":"iu","label":"ask why he's calling"},{"type":"avoidsAny","words":["me llamas","puedo ayudarte"],"label":"use usted, not tú"}],"focus":"g:cleft-focus","next":"t2"},{"id":"t2","npc":"Camilo: Queremos entrevistarlo en vivo. Lo que más nos interesa es la historia del loro.","npcEn":"Camilo: We'd like to interview you live. What interests us most is the story of the parrot.","intent":"Say that what you want to talk about is Rosa, not only the parrot (Lo que ... es ...).","accept":["Lo que quiero contar es la historia de mi abuela, no solo la del loro.","Lo que más me importa es hablar de Rosa y del barrio.","Lo que quiero es hablar de Rosa y del barrio."],"require":[{"type":"regex","pattern":"\\blo que\\b.*\\bes\\b","flags":"iu","label":"use lo que ... es ..."}],"focus":"g:cleft-focus","next":"t3"},{"id":"t3","npc":"Camilo: Entendido. Anoche el pódcast llegó al número uno. ¿Le sorprende?","npcEn":"Camilo: Understood. Last night the podcast reached number one. Does that surprise you?","intent":"Say you hadn't realised it, or hadn't thought so many people would listen (No noté / No pensé que ...).","accept":["No imaginé que tanta gente nos escuchara.","No pensé que tanta gente lo escuchara.","No creí que llegáramos al número uno."],"require":[{"type":"regex","pattern":"\\bno (noté|pensé|creí|imaginé) que\\b","flags":"iu","label":"start with no noté / no pensé que"},{"type":"regex","pattern":"(uviera|ara|iera|áramos|iéramos)\\b","flags":"iu","label":"use the past subjunctive after it"}],"focus":"g:subj-perception-negated","next":"t4"},{"id":"t4","npc":"Camilo: Perfecto. ¿Podría venir el viernes a las siete? Es en directo.","npcEn":"Camilo: Perfect. Could you come on Friday at seven? It's live.","intent":"Say Friday isn't possible but Saturday is (put the day first).","accept":["El viernes no puedo, pero el sábado sí.","El sábado puedo, el viernes no.","El viernes lo tengo ocupado, pero el sábado no tengo problema."],"require":[{"type":"negation","label":"say what is not possible"},{"type":"regex","pattern":"\\bsábado\\b","flags":"iu","label":"name Saturday"}],"focus":"g:topic-fronting","next":"t5"},{"id":"t5","npc":"Camilo: Quedamos el sábado, entonces. Gracias, y felicitaciones.","npcEn":"Camilo: Saturday it is, then. Thank you, and congratulations.","intent":"Thank him and say you'll bring Simón (use an intensifier to describe him).","accept":["Muchas gracias, hasta el sábado. Llevo a Simón, pero está súper nervioso.","Gracias a usted. Simón irá conmigo y es realmente bueno hablando.","Gracias, Camilo. Llevaré a Simón, que es muy simpático."],"require":[{"type":"regex","pattern":"\\bsimón\\b","flags":"iu","label":"mention Simón"},{"type":"regex","pattern":"\\b(súper|super|totalmente|realmente|demasiado|muy|tan)\\b","flags":"iu","label":"add an intensifier"}],"focus":"p:intensificadores","next":null}],"r":["g:cleft-focus","g:gender-articles","g:gustar-full","g:present-ar","g:present-er-ir","g:ser-identity","g:subj-perception-negated","g:topic-fronting","p:intensificadores"],"d":423,"spare":true},
{"id":"sc-u48-a","unit":"u48","band":"B2","title":"Las paredes hablan","brief":"You're Tomás, showing the house to Clemencia Galindo, the architect the Institute has sent to survey it. She's a professional you've just met, so use usted. Describe the walls, the tiles and who was standing where.","turns":[{"id":"t1","npc":"Clemencia: Buenos días. Soy Clemencia Galindo, la arquitecta del Instituto. ¿Por dónde quiere que empecemos?","npcEn":"Clemencia: Good morning. I'm Clemencia Galindo, the architect from the Institute. Where would you like us to start?","intent":"Greet her and suggest starting with the wall by the green door.","accept":["Buenos días, arquitecta. Podemos empezar por la pared de la puerta verde.","Mucho gusto. Si quiere, empezamos por el muro de la puerta verde.","Bienvenida. Le propongo empezar por la pared de la puerta verde."],"require":[{"type":"regex","pattern":"\\b(muro|pared)\\b","flags":"iu","label":"say which wall"}],"focus":"g:relatives-formal","next":"t2"},{"id":"t2","npc":"Clemencia: ¡Qué grosor tiene este muro! ¿De qué está hecho?","npcEn":"Clemencia: How thick this wall is! What is it made of?","intent":"Say the walls, which are sixty centimetres thick, are made of adobe (use a relative: que, la cual).","accept":["Las paredes, que miden sesenta centímetros de grosor, son de adobe.","Es de adobe. El muro, que tiene sesenta centímetros, es original.","Es de adobe. Las paredes, las cuales tienen sesenta centímetros de grosor, son originales."],"require":[{"type":"regex","pattern":"\\b(que|la cual|las cuales|el cual|los cuales|cuyo|cuya|cuyos|cuyas)\\b","flags":"iu","label":"use a relative: que, la cual, cuyo"}],"focus":"g:relatives-formal","next":"t3"},{"id":"t3","npc":"Clemencia: ¿Y las baldosas? ¿Son originales?","npcEn":"Marisol: And the tiles? Are they original?","intent":"Say yes: the tiles, laid almost a hundred years ago, are original (use a participle clause: colocadas).","accept":["Sí, las baldosas, colocadas hace casi cien años, son originales.","Sí, son originales. Colocadas en los años veinte, siguen casi perfectas.","Las baldosas, colocadas cuando se construyó la casa, son originales."],"require":[{"type":"regex","pattern":"\\b\\w+(ado|ada|ados|adas|ido|ida|idos|idas|ando|iendo)\\b","flags":"iu","label":"add a participle or gerund clause"}],"focus":"g:participle-gerund-clauses","next":"t4"},{"id":"t4","npc":"Clemencia: Veo una grieta en la viga. ¿Quiénes trabajan en la obra de al lado?","npcEn":"Clemencia: I see a crack in the beam. Who works on the site next door?","intent":"Say the ones in yellow helmets, and that this morning they were standing right by your wall (use: los de...).","accept":["Los del casco amarillo. Esta mañana estaban parados junto a nuestra pared.","Los de casco amarillo trabajan ahí, y hoy estaban parados al lado del muro.","Son los del casco amarillo. Esta mañana se detuvieron junto al muro a mirar la grieta."],"require":[{"type":"regex","pattern":"\\b(los|las) del?\\b","flags":"iu","label":"use: los de + the detail"}],"focus":"p:los-de-la-camiseta","next":"t5"},{"id":"t5","npc":"Clemencia: Gracias. Le mando el informe el lunes.","npcEn":"Clemencia: Thank you. I'll send you the report on Monday.","intent":"Thank her and offer her a coffee before she leaves.","accept":["Muchas gracias, arquitecta. ¿Le ofrezco un tinto antes de irse?","Gracias a usted. ¿Quiere un café antes de salir?","Se lo agradezco mucho. Antes de irse, ¿le sirvo un tinto?"],"require":[{"type":"regex","pattern":"(tinto|café)","flags":"iu","label":"offer a coffee"}],"focus":"g:relatives-formal","next":null}],"r":["g:gender-articles","g:participle-gerund-clauses","g:present-ar","g:relatives-formal","g:ser-identity","g:stem-boot","p:los-de-la-camiseta"],"d":null},
{"id":"sc-u48-b","unit":"u48","band":"B2","title":"El que se apoyó","brief":"You're Tomás in the middle of the survey. Don Hernando has just leaned on a wall the architect told him not to touch, and she has told him off. Hernando is older, so use usted with him; Clemencia too. Apologise, reassure him and explain the wall.","turns":[{"id":"t1","npc":"Hernando: ¿Qué hace la arquitecta con ese aparato, mijo?","npcEn":"Hernando: What is the architect doing with that device, son?","intent":"Tell him she's measuring the crack, trying to find out when it started (use a gerund: midiendo, tratando).","accept":["Está midiendo la grieta, tratando de saber cuándo empezó.","Va midiendo el muro, buscando el origen de la grieta.","La arquitecta está revisando la viga, midiendo cada grieta."],"require":[{"type":"regex","pattern":"\\b\\w+(ando|iendo)\\b","flags":"iu","label":"use a gerund clause"}],"focus":"g:participle-gerund-clauses","next":"t2"},{"id":"t2","npc":"Clemencia: ¡Su amigo estaba apoyado en la pared del agujero! Esa pared no se toca.","npcEn":"Clemencia: Your friend was leaning on the wall with the hole! That wall is not to be touched.","intent":"Apologise to her for not having warned him (use: haber + participle).","accept":["Perdón por no haberle avisado.","Disculpe, arquitecta, por no haberle avisado a tiempo.","Lo siento mucho, fue mi culpa por no haberle dicho nada a don Hernando."],"require":[{"type":"regex","pattern":"\\bhaber(me|te|le|lo|la|nos|les|las|los)?\\s+\\w+(ado|ido|to|cho)\\b","flags":"iu","label":"use haber + participle: haber llamado, haberle avisado"}],"focus":"g:infinitive-perfect","next":"t3"},{"id":"t3","npc":"Hernando: ¡Qué vergüenza, Tomás! ¿Y si por mi culpa se cae la viga?","npcEn":"Hernando: How embarrassing, Tomás! What if the beam falls because of me?","intent":"Reassure him: tell him not to worry, the crack in the beam comes from the vibrations of the demolition. Use usted, not tú.","accept":["No se preocupe, don Hernando. La grieta viene de las vibraciones de la demolición.","Tranquilo, don Hernando. Usted no tiene la culpa; son las vibraciones de la demolición.","No se preocupe. La grieta se debe a las vibraciones de la obra de al lado."],"require":[{"type":"regex","pattern":"\\bvibraciones\\b","flags":"iu","label":"name the cause: vibraciones"},{"type":"avoidsAny","words":["eres","tienes","tú","te preocupes"],"label":"use usted with don Hernando"}],"focus":"g:relatives-formal","next":"t4"},{"id":"t4","npc":"Clemencia: ¿Alguien anotó las medidas de ayer?","npcEn":"Marisol: Did anyone write down yesterday's measurements?","intent":"Say you think you saved them on your phone (use: Creo haber...).","accept":["Creo haberlas guardado en mi celular.","Estoy seguro de haberlas anotado en mi celular.","Me parece haberlas guardado, arquitecta. Las busco ahora."],"require":[{"type":"regex","pattern":"\\bhaber(me|te|le|lo|la|nos|les|las|los)?\\s+\\w+(ado|ido|to|cho)\\b","flags":"iu","label":"use haber + participle: haber llamado, haberle avisado"}],"focus":"p:same-subject-haber","next":"t5"},{"id":"t5","npc":"Hernando: Prometo no volver a tocar nada. ¿Qué clase de pared es esta?","npcEn":"Hernando: I promise not to touch anything again. What kind of wall is this?","intent":"Tell him, with a smile, the wall is adobe: resistant to cold and heat, but not to him (use: resistente a).","accept":["Es de adobe, que es resistente al frío y al calor, pero no a usted.","Es una pared de adobe. Es resistente al frío, pero no a sus manos, don Hernando.","Adobe, don Hernando: resistente a cien años de lluvia, pero no a usted."],"require":[{"type":"regex","pattern":"\\bresistente\\s+al?\\b","flags":"iu","label":"use: resistente a"}],"focus":"p:resistente-a","next":null}],"r":["g:demonstratives","g:gender-articles","g:infinitive-perfect","g:participle-gerund-clauses","g:present-er-ir","g:questions","g:relatives-formal","p:resistente-a","p:same-subject-haber"],"d":null},
{"id":"sc-u48-c","unit":"u48","band":"B2","title":"Preguntas para el periódico","brief":"You're Tomás, talking with Mariana, the journalist, about the architect's report. She's your friend, so use tú. Describe the building, name the cause, own up to a regret and say what the report means.","turns":[{"id":"t1","npc":"Mariana: Tomás, escribo sobre el informe. ¿Cómo describirías el edificio?","npcEn":"Mariana: Tomás, I'm writing about the report. How would you describe the building?","intent":"Say it's a 1920s building with adobe walls that are sixty centimetres thick (use a relative: que, el cual).","accept":["Es un edificio de los años veinte, con paredes de adobe que miden sesenta centímetros.","Es un edificio de 1923. Las paredes, que son de adobe, miden sesenta centímetros.","Es una casa de los años veinte. Sus muros, los cuales son de adobe, tienen sesenta centímetros de grosor."],"require":[{"type":"regex","pattern":"\\b(que|la cual|las cuales|el cual|los cuales|cuyo|cuya|cuyos|cuyas)\\b","flags":"iu","label":"use a relative: que, la cual, cuyo"}],"focus":"g:relatives-formal","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y la grieta? ¿Qué la causó?","npcEn":"Mariana: And the crack? What caused it?","intent":"Say the beam, damaged by the vibrations of the demolition, is cracked (use a participle: dañada).","accept":["La viga, dañada por las vibraciones de la demolición, está agrietada.","La grieta, causada por las vibraciones, está en la viga.","La viga, afectada por las vibraciones de la obra, se agrietó."],"require":[{"type":"regex","pattern":"\\b\\w+(ado|ada|ados|adas|ido|ida|idos|idas|ando|iendo)\\b","flags":"iu","label":"add a participle or gerund clause"},{"type":"regex","pattern":"\\bvibraciones\\b","flags":"iu","label":"name the cause: vibraciones"}],"focus":"g:participle-gerund-clauses","next":"t3"},{"id":"t3","npc":"Mariana: ¿Te arrepientes de algo?","npcEn":"Mariana: Do you regret anything?","intent":"Say you regret not having done something sooner, like calling an architect (use: haber + participle).","accept":["Me da pena no haber llamado antes a una arquitecta.","Me da pena no haber pedido el informe antes.","Me da pena no haber revisado la viga hace meses."],"require":[{"type":"regex","pattern":"\\bhaber(me|te|le|lo|la|nos|les|las|los)?\\s+\\w+(ado|ido|to|cho)\\b","flags":"iu","label":"use haber + participle: haber llamado, haberle avisado"}],"focus":"g:infinitive-perfect","next":"t4"},{"id":"t4","npc":"Mariana: ¿Qué significa el informe para ustedes?","npcEn":"Mariana: What does the report mean for you all?","intent":"Say it's the proof you can defend the building with (use a preposition + la que/la cual).","accept":["Es la prueba con la que podemos defender el edificio.","Es el documento en el cual confiamos.","Es la prueba de la que depende el futuro del café."],"require":[{"type":"regex","pattern":"\\b(en|de|con|a|para|por)\\s+(el|la|los|las)\\s+(que|cual|cuales)\\b","flags":"iu","label":"use a preposition + el/la que or el/la cual"}],"focus":"g:relatives-formal","next":"t5"},{"id":"t5","npc":"Mariana: Gracias, Tomás. Me voy corriendo.","npcEn":"Mariana: Thanks, Tomás. I have to rush off.","intent":"Thank her and invite her for a coffee at the café one day.","accept":["Gracias a ti, Mariana. Pasa por el café un día y te invito a un tinto.","Gracias por venir. Un día de estos te invito a un café.","Gracias a ti. Ven cuando quieras, el café va por mi cuenta."],"require":[{"type":"avoidsAny","words":["usted","le "],"label":"use tú with Mariana"}],"focus":"g:relatives-formal","next":null}],"r":["g:gender-articles","g:infinitive-perfect","g:participle-gerund-clauses","g:questions","g:relatives-formal"],"d":null},
{"id":"sc-u48-d","unit":"u48","band":"B2","title":"El horno nuevo","brief":"You're Tomás on the phone with Raúl, who sells kitchen equipment and has just sent you photos of an oven. Vale needs a new one. He's a stranger, so use usted. Describe what you need, and ask about the material, the shape and the weight.","turns":[{"id":"t1","npc":"Raúl: Equipos Andina, buenas tardes. ¿En qué le puedo ayudar?","npcEn":"Raúl: Equipos Andina, good afternoon. How can I help you?","intent":"Say you need an oven for a pastry kitchen, one that stands up to heavy daily use (use: resistente a).","accept":["Buenas tardes. Necesito un horno para una pastelería, resistente al uso diario.","Necesito un horno de pastelería que sea resistente al uso diario.","Hola. Busco un horno de metal, resistente al uso diario, para una pastelería."],"require":[{"type":"regex","pattern":"\\bresistente\\s+al?\\b","flags":"iu","label":"use: resistente a"}],"focus":"p:resistente-a","next":"t2"},{"id":"t2","npc":"Raúl: Tengo uno que pesa ciento veinte kilos. ¿Le cabe en la cocina?","npcEn":"Raúl: I have one that weighs one hundred and twenty kilos. Will it fit in your kitchen?","intent":"Say yes, and ask what it is made of (use: fabricado).","accept":["Sí, nos cabe. ¿Con qué está fabricado?","Creo que sí. ¿El horno está fabricado con hierro?","Sí, cabe. ¿Está fabricado con hierro o con un metal más ligero?"],"require":[{"type":"regex","pattern":"\\bfabricad[oa]s?\\b","flags":"iu","label":"use: fabricado"},{"type":"question"}],"focus":"p:fabricado-con-contener","next":"t3"},{"id":"t3","npc":"Raúl: Está fabricado con hierro, y la puerta es de vidrio. Es de color gris oscuro.","npcEn":"Raúl: It's made of iron, and the door is glass. It's dark grey.","intent":"Ask whether the oven has a rectangular shape (use: tener forma de, or forma rectangular).","accept":["¿El horno tiene forma rectangular?","¿Tiene forma de caja? Necesito que quepa bajo el mesón.","Perdone, ¿qué forma tiene? ¿Es rectangular?"],"require":[{"type":"regex","pattern":"\\bforma\\b","flags":"iu","label":"ask about the shape: forma"},{"type":"question"}],"focus":"p:tener-forma-de","next":"t4"},{"id":"t4","npc":"Raúl: Sí, rectangular. Lo que más le gusta a la gente es lo fácil que se limpia.","npcEn":"Raúl: Yes, rectangular. What people like most is how easy it is to clean.","intent":"React: say what you like about it, from the photos (use: lo + adjective + que).","accept":["Me encanta lo bonito que es.","Me gusta lo poco que pesa la puerta.","Con lo bueno que es, lo compramos."],"require":[{"type":"regex","pattern":"\\blo\\s+\\S+\\s+que\\b","flags":"iu","label":"use: lo + adjective + que"}],"focus":"g:lo-que-intensity","next":"t5"},{"id":"t5","npc":"Raúl: ¿Se lo llevo el viernes? Viene en una caja de madera.","npcEn":"Raúl: Shall I bring it to you on Friday? It comes in a wooden crate.","intent":"Say Friday is fine and ask how much it weighs with the crate (use: pesar).","accept":["Sí, el viernes está bien. ¿Y cuánto pesa con la caja?","Perfecto, el viernes. ¿Cuánto pesa el horno con la caja?","El viernes me sirve, gracias. Con la caja, ¿cuánto pesa?"],"require":[{"type":"regex","pattern":"\\bviernes\\b","flags":"iu","label":"confirm Friday"},{"type":"regex","pattern":"\\bpesa\\b","flags":"iu","label":"ask the weight: pesa"}],"focus":"p:pesar-pesarse","next":null}],"r":["g:gender-articles","g:lo-que-intensity","g:present-ar","g:ser-identity","g:stem-boot","p:fabricado-con-contener","p:pesar-pesarse","p:resistente-a","p:tener-forma-de"],"d":null,"spare":true},
{"id":"sc-u48-e","unit":"u48","band":"B2","title":"El cartel de la fachada","brief":"You're Tomás with Daniela, a young designer, who is making the poster for the launch of the heritage campaign. She's your age, so use tú. Say what the poster consists of and what the building is like.","turns":[{"id":"t1","npc":"Daniela: Hola, Tomás. Ya tengo el borrador del cartel para el lanzamiento. ¿Qué debe decir?","npcEn":"Daniela: Hi, Tomás. I already have the draft of the poster for the launch. What should it say?","intent":"Suggest a first line: built almost a hundred years ago, the building is still standing (start with a participle: Construido...).","accept":["Construido hace casi cien años, el edificio sigue en pie.","Debe decir: Construido hace casi cien años, el edificio sigue en pie.","Algo así: Construido en los años veinte, el edificio sigue en pie."],"require":[{"type":"regex","pattern":"\\bconstruid[oa]\\b","flags":"iu","label":"start with a participle: Construido"}],"focus":"g:participle-gerund-clauses","next":"t2"},{"id":"t2","npc":"Daniela: Y el texto, ¿cómo lo organizo?","npcEn":"Daniela: And the text, how do I organise it?","intent":"Say the text divides into three parts (use: se divide en).","accept":["El texto se divide en tres partes: historia, materiales y futuro.","Se divide en tres partes.","El cartel se divide en tres partes, una para cada tema."],"require":[{"type":"regex","pattern":"\\bse\\s+divide\\s+en\\b","flags":"iu","label":"use: se divide en"}],"focus":"p:se-divide-en","next":"t3"},{"id":"t3","npc":"Daniela: ¿Y la campaña? ¿En qué consiste exactamente?","npcEn":"Daniela: And the campaign? What exactly does it involve?","intent":"Say it consists of a night of music and an exhibition about the building (use: consiste en).","accept":["Consiste en una noche de música y una exposición sobre el edificio.","La campaña consiste en una exposición y un concierto en el café.","Consiste en una noche de música y una exposición sobre la historia del barrio."],"require":[{"type":"regex","pattern":"\\bconsiste\\s+en\\b","flags":"iu","label":"use: consiste en"}],"focus":"p:consistir-en","next":"t4"},{"id":"t4","npc":"Daniela: Hay gente que dice que la campaña no sirve. Lo que me molesta es que se rinden antes de intentarlo.","npcEn":"Daniela: Some people say the campaign is useless. What bothers me is that they give up before trying.","intent":"Say that what matters to you is the history of the building (use: lo que).","accept":["Lo que me importa es la historia del edificio.","Para mí, lo que importa es el futuro del barrio.","Lo que quiero es proteger el edificio."],"require":[{"type":"regex","pattern":"\\blo\\s+que\\b","flags":"iu","label":"use: lo que"}],"focus":"x:lo-que-el-que","next":"t5"},{"id":"t5","npc":"Daniela: Te mando el cartel esta noche. ¿Lo revisas?","npcEn":"Daniela: I'll send you the poster tonight. Will you check it?","intent":"Say yes, and thank her.","accept":["Claro que sí. Gracias, Daniela.","Sí, lo reviso esta noche. Muchas gracias.","Por supuesto, y gracias por todo el trabajo."],"require":[{"type":"regex","pattern":"\\bgracias\\b","flags":"iu","label":"thank her"}],"focus":"p:presenting-to-audience","next":null}],"r":["g:direct-objects","g:gender-articles","g:participle-gerund-clauses","g:present-ar","g:present-er-ir","g:questions","p:consistir-en","p:presenting-to-audience","p:se-divide-en","x:lo-que-el-que"],"d":null,"spare":true},
{"id":"sc-u48-f","unit":"u48","band":"B2","title":"Visita con estudiantes","brief":"You're Tomás giving a short tour of the café to a group of architecture students and their teacher, Profesora Salazar. She's older and a stranger, so use usted with her. Present the building, compare it, describe the colours and answer a question.","turns":[{"id":"t1","npc":"Profesora Salazar: Buenas tardes. Los estudiantes vienen a ver el edificio. ¿Nos lo presenta?","npcEn":"Profesora Salazar: Good afternoon. The students have come to see the building. Will you present it to us?","intent":"Welcome the group and say: as you can see, the walls are made of adobe (use: como pueden ver).","accept":["Bienvenidos. Como pueden ver, las paredes son de adobe.","Buenas tardes a todos. Como pueden ver, el edificio es de adobe.","Gracias por venir. Como pueden ver, los muros son de adobe."],"require":[{"type":"regex","pattern":"\\bcomo\\s+pueden\\s+ver\\b","flags":"iu","label":"use: como pueden ver"}],"focus":"p:presenting-to-audience","next":"t2"},{"id":"t2","npc":"Profesora Salazar: ¿Qué diferencia hay con un edificio moderno?","npcEn":"Profesora Salazar: How is it different from a modern building?","intent":"Compare it: in comparison with a modern building, this one keeps the heat better (use: en comparación con).","accept":["En comparación con un edificio moderno, este conserva mejor el calor.","A diferencia de un edificio moderno, este mantiene el calor.","En comparación con los edificios de cemento, este es más fresco."],"require":[{"type":"regex","pattern":"\\b(en comparación con|a diferencia de)\\b","flags":"iu","label":"use: en comparación con / a diferencia de"}],"focus":"p:en-comparacion-con","next":"t3"},{"id":"t3","npc":"Estudiante: ¿De qué color son las puertas?","npcEn":"Student: What colour are the doors?","intent":"Say the doors are dark blue and the windows dark green (use the compound colours, invariable).","accept":["Las puertas son azul oscuro y las ventanas, verde oscuro.","Son azul oscuro, y los marcos de las ventanas son verde oscuro.","Azul oscuro, y las ventanas son verde oscuro."],"require":[{"type":"regex","pattern":"\\bazul\\s+oscuro\\b","flags":"iu","label":"use the compound colour: azul oscuro"}],"focus":"p:azul-oscuro-invariable","next":"t4"},{"id":"t4","npc":"Profesora Salazar: ¿Y cuánto mide el patio?","npcEn":"Profesora Salazar: And how big is the patio?","intent":"Say it is about six metres long, along the whole east wall (use: a lo largo de).","accept":["Mide unos seis metros a lo largo de todo el muro este.","Tiene unos seis metros y va a lo largo del muro este.","Unos seis metros, a lo largo de la pared del fondo."],"require":[{"type":"regex","pattern":"\\ba\\s+lo\\s+largo\\s+del?\\b","flags":"iu","label":"use: a lo largo de"}],"focus":"p:a-lo-largo-de","next":"t5"},{"id":"t5","npc":"Profesora Salazar: Muchas gracias, fue muy claro.","npcEn":"Profesora Salazar: Thank you very much, that was very clear.","intent":"Thank her and say the students are welcome to come back.","accept":["Gracias a usted. Los estudiantes pueden volver cuando quieran.","Fue un placer. Pueden volver cuando quieran.","Muchas gracias por la visita. Aquí siempre son bienvenidos."],"require":[{"type":"avoidsAny","words":["eres","tienes"],"label":"use usted"}],"focus":"p:caracterizarse-por","next":null}],"r":["g:gender-articles","g:questions","g:ser-identity","p:a-lo-largo-de","p:azul-oscuro-invariable","p:caracterizarse-por","p:en-comparacion-con","p:presenting-to-audience"],"d":488,"spare":true},
{"id":"sc-u49-a","unit":"u49","band":"B2","title":"La carta a la alcaldía","brief":"You're Tomás, drafting a formal complaint about the demolition with Mariana, who is your friend, so use tú with her. Write the letter's lines out loud: the opening, a polite request, a deadline and the attachments.","turns":[{"id":"t1","npc":"Mariana: Bueno, la carta a la alcaldía. ¿Cómo la empiezas?","npcEn":"Mariana: Right, the letter to the mayor's office. How do you begin?","intent":"Open the letter by saying you are writing to them to make a complaint (use: Me dirijo a ustedes para...).","accept":["Estimados señores: me dirijo a ustedes para presentar una queja.","Señores: me dirijo a ustedes para presentar una queja por la demolición.","Me dirijo a ustedes para presentar una queja formal."],"require":[{"type":"regex","pattern":"\\bme dirijo a ustedes para\\b","flags":"iu","label":"start with: me dirijo a ustedes para..."}],"focus":"p:dirigirse-a","next":"t2"},{"id":"t2","npc":"Mariana: Bien. Ahora lo importante: ¿qué quieres que hagan?","npcEn":"Mariana: Good. Now the important part: what do you want them to do?","intent":"Ask them politely to stop the demolition (use: Les ruego que + subjunctive).","accept":["Les ruego que suspendan la demolición del edificio.","Les ruego que detengan la demolición hasta la audiencia.","Les ruego que revisen el permiso de la demolición."],"require":[{"type":"regex","pattern":"\\bles ruego que\\b","flags":"iu","label":"use: les ruego que..."},{"type":"subjunctiveAfter","trigger":"ruego que","label":"after ruego que, use the subjunctive (suspendan, detengan)"}],"focus":"p:le-ruego-que","next":"t3"},{"id":"t3","npc":"Mariana: Hay que poner una fecha, o no van a contestar.","npcEn":"Mariana: We have to put a date, or they won't answer.","intent":"Close the argument by saying that, for all the above reasons, you ask them to answer within fifteen days (use: Por todo lo anterior, les ruego que...).","accept":["Por todo lo anterior, les ruego que me respondan en quince días.","Por todo lo anterior, les ruego que respondan en un plazo de quince días.","Por todo lo anterior, les ruego que suspendan la demolición en quince días."],"require":[{"type":"regex","pattern":"\\bpor todo lo anterior,? les ruego que\\b","flags":"iu","label":"close with: por todo lo anterior, les ruego que..."}],"focus":"p:le-ruego-que","next":"t4"},{"id":"t4","npc":"Mariana: ¿Y qué les decimos a los funcionarios, además del plazo?","npcEn":"Mariana: And what do we tell the officials, besides the deadline?","intent":"Say you ask for their help to protect the building (use: Les pedimos su ayuda para...).","accept":["Les pedimos su ayuda para proteger el edificio.","Les pedimos su ayuda para salvar el café y el barrio.","Les pedimos su ayuda para que el edificio no se pierda."],"require":[{"type":"regex","pattern":"\\bles pedimos su ayuda\\b","flags":"iu","label":"use: les pedimos su ayuda..."}],"focus":"p:preguntar-pedir","next":"t5"},{"id":"t5","npc":"Mariana: ¿Mando la carta con algún documento?","npcEn":"Mariana: Shall I send the letter with a document?","intent":"Say yes, and that you attach the neighbours' signatures (use: Adjunto les envío...).","accept":["Sí, adjunto les envío las firmas de los vecinos.","Adjunto les envío las firmas de todos los vecinos.","Sí, adjunto les envío las firmas y una foto del edificio."],"require":[{"type":"regex","pattern":"\\badjunto les envío\\b","flags":"iu","label":"use: adjunto les envío..."}],"focus":"p:adjunto-envio","next":"t6"},{"id":"t6","npc":"Mariana: Listo. La envío hoy. ¿Te invito a un tinto?","npcEn":"Mariana: Done. I'll send it today. Shall I buy you a coffee?","intent":"Accept warmly and thank her.","accept":["Claro, gracias, Mariana. Muchas gracias por tu ayuda.","Sí, por favor. Gracias por todo.","Con mucho gusto, y gracias por la ayuda."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:formal-letter-grammar","g:gender-articles","g:present-ar","g:questions","g:stem-boot","p:adjunto-envio","p:dirigirse-a","p:le-ruego-que","p:preguntar-pedir"],"d":473},
{"id":"sc-u49-b","unit":"u49","band":"B2","title":"Suena a mi banco","brief":"You're Tomás, talking to Vale about the letter to Yesid's family proposing a joint business. Vale is quick and dry, and a friend, so use tú. Explain what the letter is about, what each side has, and what it depends on.","turns":[{"id":"t1","npc":"Vale: Leí tu borrador para la familia de Yesid. Suena a mi banco. ¿De qué se trata?","npcEn":"Vale: I read your draft for Yesid's family. It sounds like my bank. What is it about?","intent":"Say the letter is about a proposal to work together (use: Se trata de...).","accept":["Se trata de una propuesta para trabajar juntos.","Se trata de un negocio entre el café y la familia.","Se trata de una propuesta para la familia de Yesid."],"require":[{"type":"regex","pattern":"\\bse trata de\\b","flags":"iu","label":"use: se trata de..."}],"focus":"g:verbs-prepositions","next":"t2"},{"id":"t2","npc":"Vale: ¿Y qué tienen ellos que no tenemos nosotros?","npcEn":"Vale: And what do they have that we don't?","intent":"Say they have a good supply of coffee (use: disponer de, e.g. Ellos disponen de...).","accept":["Ellos disponen de un buen suministro de café.","Disponen de un suministro de café muy bueno.","La familia dispone de café de la mejor calidad."],"require":[{"type":"regex","pattern":"\\bdispon(e|en)\\s+de\\b","flags":"iu","label":"use: dispone de / disponen de"}],"focus":"p:disponer-de","next":"t3"},{"id":"t3","npc":"Vale: ¿Y nosotros qué ponemos?","npcEn":"Vale: And what do we put in?","intent":"Say we count on the café and its good customers (use: Contamos con...).","accept":["Contamos con el café y con muchos buenos clientes.","Nosotros contamos con la cocina y el local.","Contamos con el apoyo de los clientes del barrio."],"require":[{"type":"regex","pattern":"\\bcontamos con\\b","flags":"iu","label":"use: contamos con..."}],"focus":"g:verbs-prepositions","next":"t4"},{"id":"t4","npc":"Vale: ¿Y si la familia dice que no? Yo no tengo plan B.","npcEn":"Vale: And if the family says no? I don't have a plan B.","intent":"Say it depends on them and you will wait for their answer (use: Depende de...).","accept":["Eso depende de ellos. Esperamos su respuesta.","Depende de la respuesta de la familia.","Todo depende de ellos, pero yo tengo esperanza."],"require":[{"type":"regex","pattern":"\\bdepende de\\b","flags":"iu","label":"use: depende de..."}],"focus":"g:verbs-prepositions","next":"t5"},{"id":"t5","npc":"Vale: Yesid va a preguntar cómo funciona el negocio. ¿Qué le digo?","npcEn":"Vale: Yesid is going to ask how the business works. What do I tell him?","intent":"Explain that it consists of sharing the costs and the profits (use: Consiste en...).","accept":["Consiste en compartir los gastos y las ganancias.","El negocio consiste en trabajar juntos y compartir.","Consiste en que todos ponemos algo y todos ganamos."],"require":[{"type":"regex","pattern":"\\bconsiste en\\b","flags":"iu","label":"use: consiste en..."}],"focus":"g:verbs-prepositions","next":"t6"},{"id":"t6","npc":"Vale: Mejor. Ahora suenas casi como una persona. ¿Se la mandas hoy?","npcEn":"Vale: Better. Now you almost sound like a person. Are you sending it to them today?","intent":"Say yes, you will send it this afternoon, and thank her for the help.","accept":["Sí, se la envío esta tarde. Gracias por la ayuda, Vale.","Sí, hoy mismo. Gracias por todo.","Sí, hoy por la tarde. Muchas gracias por tu ayuda."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:formal-letter-grammar","g:gender-articles","g:present-ar","g:present-er-ir","g:questions","g:stem-boot","g:that-clauses","g:verbs-prepositions","g:yo-irregular","p:disponer-de"],"d":432},
{"id":"sc-u49-c","unit":"u49","band":"B2","title":"Ventanilla de patrimonio","brief":"You're Tomás, writing in the online chat of the heritage institute to ask about protection for the café. The official, Señora Ortega, is a stranger, so use usted, and ustedes for the institute. Be formal and clear.","turns":[{"id":"t1","npc":"Señora Ortega: Instituto de Patrimonio, atención en línea. Buenas tardes, ¿en qué le puedo ayudar?","npcEn":"Señora Ortega: Heritage Institute, online help. Good afternoon, how can I help you?","intent":"Say you are writing to them to request information about protecting a building (use: Me dirijo a ustedes para solicitar información).","accept":["Buenas tardes. Me dirijo a ustedes para solicitar información sobre la protección de un edificio.","Me dirijo a ustedes para solicitar información sobre el patrimonio.","Buenas tardes, señora. Me dirijo a ustedes para solicitar información."],"require":[{"type":"regex","pattern":"\\bme dirijo a ustedes para solicitar\\b","flags":"iu","label":"use: me dirijo a ustedes para solicitar..."}],"focus":"p:dirigirse-a","next":"t2"},{"id":"t2","npc":"Señora Ortega: ¿De qué edificio se trata?","npcEn":"Señora Ortega: Which building is it?","intent":"Say it is a café in La Candelaria that belonged to your grandmother Rosa (use: Se trata de...).","accept":["Se trata de un café en La Candelaria, de mi abuela Rosa.","Se trata del café de mi abuela Rosa, en La Candelaria.","Se trata de un café antiguo en La Candelaria."],"require":[{"type":"regex","pattern":"\\bse trata (de|del)\\b","flags":"iu","label":"use: se trata de..."}],"focus":"g:verbs-prepositions","next":"t3"},{"id":"t3","npc":"Señora Ortega: ¿A qué se dedica el local hoy?","npcEn":"Señora Ortega: What does the premises do today?","intent":"Say it is devoted to selling coffee and pastries (use: Se dedica a...).","accept":["Se dedica a la venta de café y pasteles.","El local se dedica a servir café y pan.","Se dedica a vender café y dulces."],"require":[{"type":"regex","pattern":"\\bse dedica a\\b","flags":"iu","label":"use: se dedica a..."}],"focus":"p:dedicarse-a","next":"t4"},{"id":"t4","npc":"Señora Ortega: También tenemos un programa de apoyo para arreglar fachadas antiguas. ¿Le interesa?","npcEn":"Señora Ortega: We also have a support programme for repairing old façades. Are you interested?","intent":"Say yes, you are interested in the programme (use: Estoy interesado en...).","accept":["Sí, estoy interesado en el programa.","Sí, estoy muy interesado en ese programa.","Sí, estoy interesado en arreglar la fachada del café."],"require":[{"type":"regex","pattern":"\\bestoy (muy )?interesado en\\b","flags":"iu","label":"use: estoy interesado en..."}],"focus":"p:interesado-en","next":"t5"},{"id":"t5","npc":"Señora Ortega: Perfecto. El formulario en línea está fuera de servicio hoy, pero el impreso lo puede recoger aquí el viernes.","npcEn":"Señora Ortega: Perfect. The online form is out of service today, but you can pick up the printed one here on Friday.","intent":"Say you will come to pick up the form on Friday (use: Paso a recoger...).","accept":["Paso a recoger el formulario el viernes.","Muy bien, paso a recoger el formulario el viernes por la tarde.","No hay problema. Paso a recogerlo el viernes."],"require":[{"type":"regex","pattern":"\\bpaso a recoger","flags":"iu","label":"use: paso a recoger..."}],"focus":"p:entregar-recoger","next":"t6"},{"id":"t6","npc":"Señora Ortega: Muy bien. ¿Algo más?","npcEn":"Señora Ortega: Very good. Anything else?","intent":"Thank her politely and say goodbye until Friday.","accept":["No, nada más. Gracias, señora Ortega. Hasta el viernes.","Muchas gracias, señora. Hasta el viernes.","Gracias por su ayuda. Hasta el viernes."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:formal-letter-grammar","g:gender-articles","g:present-ar","g:stem-boot","g:verb-infinitive","g:verbs-prepositions","p:dedicarse-a","p:dirigirse-a","p:entregar-recoger","p:interesado-en"],"d":473,"spare":true},
{"id":"sc-u49-d","unit":"u49","band":"B2","title":"Informe para la junta","brief":"You're Tomás, helping Don Hernando write a report for the neighbours about the project. He is courtly and older than you, so use usted. Weigh the options, talk about what you're good at and answer his personal questions.","turns":[{"id":"t1","npc":"Don Hernando: Joven Tomás, los vecinos me pidieron un informe sobre el proyecto. ¿Qué ventaja destaca usted?","npcEn":"Don Hernando: Young Tomás, the neighbours asked me for a report on the project. Which advantage do you highlight?","intent":"Say that among the advantages, saving money stands out (use: Entre las ventajas destaca...).","accept":["Entre las ventajas destaca el ahorro de dinero.","Entre las ventajas destaca el trabajo en equipo.","Entre las ventajas del proyecto destaca el ahorro de tiempo."],"require":[{"type":"regex","pattern":"\\bentre las ventajas\\b.*\\bdestaca\\b","flags":"iu","label":"use: entre las ventajas ... destaca ..."}],"focus":"p:entre-las-ventajas-destaca","next":"t2"},{"id":"t2","npc":"Don Hernando: Muy bien. ¿Y las desventajas?","npcEn":"Don Hernando: Very good. And the disadvantages?","intent":"Say that among the disadvantages, the start-up costs stand out (use: Entre las desventajas destacan...).","accept":["Entre las desventajas destacan los costos iniciales.","Entre las desventajas destacan los gastos del principio.","Entre las desventajas destacan los costos y el papeleo."],"require":[{"type":"regex","pattern":"\\bentre las desventajas\\b.*\\bdestacan?\\b","flags":"iu","label":"use: entre las desventajas ... destacan ..."}],"focus":"p:entre-las-ventajas-destaca","next":"t3"},{"id":"t3","npc":"Don Hernando: Dígame, ¿qué se le da bien a usted en el negocio?","npcEn":"Don Hernando: Tell me, what are you good at in the business?","intent":"Say you are good with numbers but bad at cooking (use: Se me dan bien... / Se me da mal...).","accept":["Se me dan bien los números, pero se me da mal cocinar.","Se me dan bien los números y se me da mal la cocina.","Se me da mal cocinar, pero se me dan bien los números."],"require":[{"type":"regex","pattern":"\\bse me (da|dan) bien\\b","flags":"iu","label":"say what you're good at: se me da(n) bien..."},{"type":"regex","pattern":"\\bse me (da|dan) mal\\b","flags":"iu","label":"say what you're bad at: se me da(n) mal..."}],"focus":"p:darsele-bien-mal","next":"t4"},{"id":"t4","npc":"Don Hernando: Me dicen que Altamira le ofreció mucho dinero por el café. ¿Es cierto?","npcEn":"Don Hernando: They tell me Altamira offered you a lot of money for the café. Is it true?","intent":"Say yes, but you are not going to give up the café (use: renunciar a...).","accept":["Sí, pero no voy a renunciar al café.","Es cierto, pero no pienso renunciar al café de mi abuela.","Sí, pero no voy a renunciar a este lugar."],"require":[{"type":"regex","pattern":"\\brenunciar (a|al)\\b","flags":"iu","label":"use: renunciar a..."},{"type":"negation"}],"focus":"p:renunciar-a","next":"t5"},{"id":"t5","npc":"Don Hernando: ¿Y cómo se siente después de tanto trabajo, joven?","npcEn":"Don Hernando: And how do you feel after so much work, young man?","intent":"Say you are happy about having inherited the café (use: de + haber + past participle).","accept":["Estoy contento de haber heredado el café.","Me alegro de haber venido a Bogotá.","Estoy feliz de haber aceptado el café de mi abuela."],"require":[{"type":"regex","pattern":"\\bhaber \\w+(ado|ido)\\b","flags":"iu","label":"use: haber + participle (haber heredado)"}],"focus":"g:infinitive-perfect","next":"t6"},{"id":"t6","npc":"Don Hernando: Excelente. Mañana les leo el informe a los vecinos. ¿Me acompaña?","npcEn":"Don Hernando: Excellent. Tomorrow I'll read the report to the neighbours. Will you come with me?","intent":"Say yes, with pleasure, and thank him for inviting you.","accept":["Claro que sí, don Hernando. Con mucho gusto.","Sí, lo acompaño. Gracias por invitarme.","Con mucho gusto, don Hernando. Muchas gracias."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:formal-letter-grammar","g:gender-articles","g:indirect-objects","g:infinitive-perfect","g:present-ar","g:questions","p:darsele-bien-mal","p:entre-las-ventajas-destaca","p:renunciar-a"],"d":null,"spare":true},
{"id":"sc-u49-e","unit":"u49","band":"B2","title":"Máquina rota","brief":"You're Tomás on the phone with Lucía, who works at a coffee equipment supplier. The new machine arrived broken. She is a stranger, so use usted. Explain the problem and politely request a replacement and a refund.","turns":[{"id":"t1","npc":"Lucía: Distribuidora Andina, habla Lucía. ¿Con quién hablo?","npcEn":"Lucía: Andean Distributors, Lucía speaking. Who am I speaking to?","intent":"Say you are Tomás, from the café in La Candelaria, and that you have a complaint.","accept":["Habla Tomás, del café de La Candelaria. Tengo una queja.","Buenas tardes, soy Tomás, del café de La Candelaria. Quiero presentar una queja.","Soy Tomás, del café. Tengo una queja sobre mi pedido."],"require":[{"type":"regex","pattern":"\\bqueja\\b","flags":"iu","label":"say you have a complaint (una queja)"}],"focus":"g:formal-letter-grammar","next":"t2"},{"id":"t2","npc":"Lucía: Dígame, ¿qué pasó?","npcEn":"Lucía: Tell me, what happened?","intent":"Say the coffee machine arrived broken.","accept":["La máquina de café llegó rota.","La máquina llegó rota el lunes.","La máquina que compramos llegó rota."],"require":[{"type":"regex","pattern":"\\brot[oa]s?\\b","flags":"iu","label":"say it arrived broken (rota)"}],"focus":"g:formal-letter-grammar","next":"t3"},{"id":"t3","npc":"Lucía: Lo lamento mucho. ¿Qué pide?","npcEn":"Lucía: I'm very sorry. What are you asking for?","intent":"Say you would be grateful if they replaced the machine before Monday (use: Le agradecería que + past subjunctive).","accept":["Le agradecería que reemplazara la máquina antes del lunes.","Le agradecería que me reemplazara la máquina antes del lunes.","Le agradecería que la reemplazaran antes del lunes."],"require":[{"type":"regex","pattern":"\\ble agradecer[ií]a que\\b","flags":"iu","label":"use: le agradecería que..."}],"focus":"g:formal-letter-grammar","next":"t4"},{"id":"t4","npc":"Lucía: El repartidor no puede pasar hasta el viernes. ¿Puede venir usted a recogerla?","npcEn":"Lucía: The delivery man can't come until Friday. Can you come to pick it up?","intent":"Say you can't, because the machine has been out of service since Monday and you can't close the café (use: fuera de servicio).","accept":["No puedo, porque la máquina está fuera de servicio desde el lunes.","No puedo ir. La máquina está fuera de servicio desde el lunes y no puedo cerrar el café.","Lo siento, no puedo. Estamos fuera de servicio desde el lunes."],"require":[{"type":"regex","pattern":"\\bfuera de servicio\\b","flags":"iu","label":"use: fuera de servicio"},{"type":"negation"}],"focus":"p:fuera-de-servicio","next":"t5"},{"id":"t5","npc":"Lucía: Entiendo. Entonces le mando la máquina nueva mañana con otro repartidor. ¿Quiere el reembolso del envío?","npcEn":"Lucía: I understand. Then I will send you the new machine tomorrow with another delivery man. Do you want the shipping refunded?","intent":"Say yes, and that you ask for the refund.","accept":["Sí, pido el reembolso del envío.","Sí, pido también el reembolso.","Sí, por favor. Pido el reembolso del envío."],"require":[{"type":"regex","pattern":"\\b(pido|solicito)\\b","flags":"iu","label":"ask for it: pido (or solicito) el reembolso"}],"focus":"g:formal-letter-grammar","next":"t6"},{"id":"t6","npc":"Lucía: Listo. Hoy le llega un correo. Que tenga buena tarde.","npcEn":"Lucía: Done. You'll get an email today. Have a good afternoon.","intent":"Thank her and say goodbye.","accept":["Muchas gracias, Lucía. Igualmente, buena tarde.","Gracias por su ayuda. Hasta luego.","Se lo agradezco mucho. Buenas tardes."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:direct-objects","g:formal-letter-grammar","g:gender-articles","g:indirect-objects","g:present-ar","g:questions","g:stem-boot","p:fuera-de-servicio"],"d":458,"spare":true},
{"id":"sc-u49-f","unit":"u49","band":"B2","title":"Una candidata","brief":"You're Tomás, interviewing Daniela, a candidate for a barista job at the café. She uses usted with you, but you may use tú with her. Ask about her work, her plans and her documents, and close the interview kindly.","turns":[{"id":"t1","npc":"Daniela: Buenos días. Vine por el anuncio del cargo de barista. Me llamo Daniela.","npcEn":"Daniela: Good morning. I came about the advertisement for the barista post. My name is Daniela.","intent":"Welcome her and ask what she does for a living (use: ¿A qué te dedicas?).","accept":["Bienvenida, Daniela. ¿A qué te dedicas ahora?","Buenos días. Siéntate, por favor. ¿A qué te dedicas?","Mucho gusto, Daniela. ¿A qué te dedicas?"],"require":[{"type":"regex","pattern":"\\ba qué te dedicas\\b","flags":"iu","label":"ask: ¿a qué te dedicas?"}],"focus":"p:dedicarse-a","next":"t2"},{"id":"t2","npc":"Daniela: Trabajo en un hotel, pero estoy interesada en un cargo con más café y más clientes.","npcEn":"Daniela: I work in a hotel, but I'm interested in a post with more coffee and more customers.","intent":"Ask whether she is going to give up the hotel (use: renunciar a...).","accept":["¿Vas a renunciar al hotel?","¿Piensas renunciar al hotel?","Entiendo. ¿Vas a renunciar al hotel?"],"require":[{"type":"regex","pattern":"\\brenunci(ar|as)\\b","flags":"iu","label":"use: renunciar a..."},{"type":"question"}],"focus":"p:renunciar-a","next":"t3"},{"id":"t3","npc":"Daniela: Todavía no. Eso depende de su respuesta.","npcEn":"Daniela: Not yet. That depends on your answer.","intent":"Say that we have a small but united team (use: Contamos con...).","accept":["Contamos con un equipo pequeño, pero muy unido.","Entiendo. Contamos con un equipo pequeño y simpático.","Contamos con cuatro personas y un loro."],"require":[{"type":"regex","pattern":"\\bcontamos con\\b","flags":"iu","label":"use: contamos con..."}],"focus":"g:verbs-prepositions","next":"t4"},{"id":"t4","npc":"Daniela: Le envié dos cartas de referencia por correo. ¿Las recibió?","npcEn":"Daniela: I sent you two letters of reference by email. Did you get them?","intent":"Say yes, and ask her to send you her CV (use: ¿Me puedes enviar tu hoja de vida?).","accept":["Sí, las tengo. ¿Me puedes enviar tu hoja de vida?","Sí, gracias. ¿Me envías también tu hoja de vida?","Sí, las recibí. ¿Puedes enviarme tu hoja de vida?"],"require":[{"type":"regex","pattern":"\\bhoja de vida\\b","flags":"iu","label":"ask for her CV (hoja de vida)"},{"type":"question"}],"focus":"p:adjunto-envio","next":"t5"},{"id":"t5","npc":"Daniela: Claro. ¿Y cuándo sabré algo?","npcEn":"Daniela: Of course. And when will I hear something?","intent":"Say you will answer after having talked to Vale (use: Después de haber hablado con...).","accept":["Después de haber hablado con Vale, te respondo.","Te respondo después de haber hablado con Vale.","Después de haber hablado con Vale, te llamo."],"require":[{"type":"regex","pattern":"\\bdespués de haber \\w+(ado|ido)\\b","flags":"iu","label":"use: después de haber + participle"}],"focus":"g:infinitive-perfect","next":"t6"},{"id":"t6","npc":"Daniela: Muchas gracias por recibirme.","npcEn":"Daniela: Thank you very much for seeing me.","intent":"Say it was a pleasure and that you will call her this week.","accept":["Con mucho gusto, Daniela. Te llamo esta semana.","Fue un placer. Te llamo el viernes.","Gracias a ti. Esta semana te llamo."],"require":[],"focus":"g:formal-letter-grammar","next":null}],"r":["g:formal-letter-grammar","g:gender-articles","g:infinitive-perfect","g:verbs-prepositions","p:adjunto-envio","p:dedicarse-a","p:renunciar-a"],"d":null,"spare":true},
{"id":"sc-u50-a","unit":"u50","band":"B2","title":"La oferta de Medellín","brief":"You're Tomás. Vale has just told you an investor will finance her own bakery in Medellín, and you want her to stay. You're close, so use tú. Say what scares you, own your bad reaction, and leave the decision with her.","turns":[{"id":"t1","npc":"Vale: Un inversionista de Medellín quiere financiar mi propia pastelería. Dime qué piensas.","npcEn":"Vale: An investor from Medellín wants to finance my own bakery. Tell me what you think.","intent":"Tell her you're afraid she won't come back (use: Tengo miedo de que + subjunctive).","accept":["Tengo miedo de que no vuelvas.","La verdad, tengo miedo de que te vayas y no vuelvas.","Tengo miedo de que ya no quieras volver al café."],"require":[{"type":"regex","pattern":"\\bmiedo de que\\b","flags":"iu","label":"say it with: tengo miedo de que + subjunctive"}],"focus":"p:tengo-miedo-de-que","next":"t2"},{"id":"t2","npc":"Vale: Siempre piensas en lo que tú necesitas. ¿Y yo qué?","npcEn":"Vale: You always think about what you need. What about me?","intent":"Admit you're embarrassed about how you reacted (use: Me da vergüenza + infinitive).","accept":["Tienes razón. Me da vergüenza hablar así.","Me da vergüenza pensar solo en mí.","Me da vergüenza haber hablado así."],"require":[{"type":"regex","pattern":"\\bme da vergüenza\\b","flags":"iu","label":"use: me da vergüenza"}],"focus":"p:me-da-verguenza","next":"t3"},{"id":"t3","npc":"Vale: Ayer dijiste que me apoyarías pasara lo que pasara.","npcEn":"Vale: Yesterday you said you would support me whatever happened.","intent":"Say that you told her you would support her (use: Te dije que + conditional).","accept":["Te dije que te apoyaría, y es verdad.","Es cierto. Te dije que te apoyaría.","Sí, te dije que te apoyaría y lo voy a hacer."],"require":[{"type":"anyVerbInTense","tense":"condicional","label":"say what you would do: te apoyaría"}],"focus":"g:subj-future-in-past","next":"t4"},{"id":"t4","npc":"Vale: Entonces, ¿qué quieres que haga?","npcEn":"Vale: So what do you want me to do?","intent":"Tell her to do whatever she wants (use: lo que + subjunctive).","accept":["Haz lo que quieras.","Lo que tú decidas estará bien.","Haz lo que sea mejor para ti."],"require":[{"type":"regex","pattern":"\\b(lo que|el que|quien|donde)\\s+(tú\\s+|usted\\s+)?(no\\s+)?\\w+(e|es|a|as|en|an)\\b","flags":"iu","label":"use a free relative: lo que quieras, lo que decidas"}],"focus":"g:subj-free-relatives","next":"t5"},{"id":"t5","npc":"Vale: Gracias por decirlo así. Voy a pensarlo con calma.","npcEn":"Vale: Thanks for putting it that way. I'm going to think it over calmly.","intent":"Say you'll be here and that she can take her time.","accept":["Aquí estaré. Tómate el tiempo que necesites.","Aquí estaré cuando decidas.","Tómate el tiempo que quieras. Aquí estaré."],"require":[],"focus":"g:subj-free-relatives","next":null}],"r":["g:questions","g:relatives-donde-lo-que","g:stem-boot","g:subj-free-relatives","g:subj-future-in-past","g:that-clauses","p:me-da-verguenza","p:tengo-miedo-de-que"],"d":null},
{"id":"sc-u50-b","unit":"u50","band":"B2","title":"Mudarse a Chía","brief":"You're Don Hernando, on the phone with your daughter Lucía, who wants you to move into her house in Chía. Like many Colombians, she calls her father usted; you call her tú. Stay firm, but don't let it end in shouting.","turns":[{"id":"t1","npc":"Lucía: Papá, ya está decidido. Usted se viene a vivir con nosotros.","npcEn":"Lucía: Dad, it's decided. You're coming to live with us.","intent":"Tell her that nobody has decided anything and that nobody should speak for you (use: Que + subjunctive).","accept":["Que nadie decida por mí.","Que no decidan por mí, Lucía.","No hay nada decidido. Que nadie hable por mí."],"require":[{"type":"regex","pattern":"\\bque\\s+(nadie|no)\\b","flags":"iu","label":"use que + subjunctive: que nadie decida por mí"}],"focus":"g:que-wishes-commands","next":"t2"},{"id":"t2","npc":"Lucía: ¡Papá, usted no puede seguir solo! ¡Me da miedo que le pase algo!","npcEn":"Lucía: Dad, you can't go on alone! I'm scared something will happen to you!","intent":"Tell her to stop shouting (use: Que + subjunctive, the repeated order).","accept":["¡Que no me grites, Lucía!","Que me hables sin gritos, por favor.","¡Que bajes la voz!"],"require":[{"type":"regex","pattern":"\\bque\\b","flags":"iu","label":"repeat the order with que: ¡que no grites!"}],"focus":"p:que-subj-repeated-order","next":"t3"},{"id":"t3","npc":"Lucía: Perdón. Es que el vecino me dijo que ayer usted hablaba a gritos con el televisor.","npcEn":"Lucía: Sorry. It's just that the neighbour told me you were shouting at the television yesterday.","intent":"Say you're sorry you made her worry (use: Siento + haber + past participle).","accept":["Siento haberte preocupado.","Siento haberte asustado, Lucía.","Siento mucho haberte preocupado."],"require":[{"type":"regex","pattern":"\\bsiento (mucho )?haber\\w*","flags":"iu","label":"use siento + haber + participle for something you did"}],"focus":"x:siento-que-vs-siento-no-haber","next":"t4"},{"id":"t4","npc":"Lucía: ¿Entonces se viene a vivir conmigo?","npcEn":"Lucía: So are you coming to live with me?","intent":"Say you're sorry that she feels alone, but you won't leave your home (use: Siento que + subjunctive).","accept":["Siento que te sientas sola, pero no me voy de mi casa.","Siento que estés preocupada, pero me quedo aquí.","Siento que no lo entiendas, pero no me voy."],"require":[{"type":"regex","pattern":"\\bsiento que\\b","flags":"iu","label":"use siento que + subjunctive for her feeling"}],"focus":"x:siento-que-vs-siento-no-haber","next":"t5"},{"id":"t5","npc":"Lucía: Está bien. Pero el domingo viene a almorzar a mi casa.","npcEn":"Lucía: Fine. But on Sunday you're coming to lunch at my place.","intent":"Agree, and say you'll bring her something sweet from the café.","accept":["Está bien. Te llevaré algo dulce del café.","De acuerdo, iré el domingo y te llevaré un postre.","Voy con gusto. Te llevo algo dulce."],"require":[],"focus":"g:que-wishes-commands","next":null}],"r":["g:estar-location-states","g:gender-articles","g:prep-pronouns","g:que-wishes-commands","g:stem-boot","g:that-clauses","p:que-subj-repeated-order","x:siento-que-vs-siento-no-haber"],"d":null},
{"id":"sc-u50-c","unit":"u50","band":"B2","title":"Una oferta sobre la mesa","brief":"You're Tomás, meeting Altamira's advisor, Señor Ruiz, at the café. He's a stranger and you are on formal terms, so use usted. You want different things, so stay polite, set a limit and aim for a deal.","turns":[{"id":"t1","npc":"Ruiz: Buenos días. Altamira quiere cerrar esto hoy. ¿Qué necesita usted?","npcEn":"Ruiz: Good morning. Altamira wants to close this today. What do you need?","intent":"Say you need more time and that you won't decide today (use usted or no form).","accept":["Necesito más tiempo. Hoy no voy a decidir nada.","Más tiempo. No puedo decidir hoy.","Buenos días. Necesito más tiempo y no decidiré hoy."],"require":[{"type":"negation","label":"say what you won't do today"}],"focus":"g:subj-future-in-past","next":"t2"},{"id":"t2","npc":"Ruiz: Le prometo que el precio será justo para quien acepte hoy.","npcEn":"Ruiz: I promise you the price will be fair for whoever accepts today.","intent":"Say that you'll sell to whoever respects the café (use: quien + subjunctive).","accept":["Le venderé a quien respete el café.","No vendo a quien no respete el café.","Venderé a quien respete la historia del café."],"require":[{"type":"regex","pattern":"\\b(quien|el que|los que)\\s+(no\\s+)?\\w+(e|en|an|a)\\b","flags":"iu","label":"use a free relative: a quien respete"}],"focus":"g:subj-free-relatives","next":"t3"},{"id":"t3","npc":"Ruiz: Con respeto, estoy harto de que todos hablen de historia y nadie quiera negociar.","npcEn":"Ruiz: With respect, I'm fed up with everyone talking about history and nobody wanting to negotiate.","intent":"Say you understand him perfectly, but it makes you angry when they treat the café like a number (use: Me da rabia que).","accept":["Lo entiendo perfectamente, pero me da rabia que traten el café como un número.","Lo entiendo, pero me da rabia que lo traten como un número.","Me da rabia que traten mi café como un número, aunque lo entiendo."],"require":[{"type":"regex","pattern":"\\bme da rabia que\\b","flags":"iu","label":"use me da rabia que + subjunctive"}],"focus":"p:me-da-rabia-me-indigna","next":"t4"},{"id":"t4","npc":"Ruiz: Tiene razón. Entonces dígame, ¿qué haría falta para llegar a un acuerdo?","npcEn":"Ruiz: You're right. So tell me, what would it take to reach an agreement?","intent":"Say it would be best if he gave you thirty days (use: Lo mejor sería que + imperfect subjunctive).","accept":["Lo mejor sería que usted me diera treinta días.","Lo mejor sería que me dieran treinta días más.","Lo mejor sería que esperáramos treinta días."],"require":[{"type":"regex","pattern":"\\blo mejor sería que\\b","flags":"iu","label":"use: lo mejor sería que + imperfect subjunctive"}],"focus":"p:lo-mejor-seria-que","next":"t5"},{"id":"t5","npc":"Ruiz: Treinta días. Lo hablaré con mi jefe. ¿Tomamos un tinto mientras tanto?","npcEn":"Ruiz: Thirty days. I'll talk to my boss. Shall we have a black coffee in the meantime?","intent":"Thank him and say the coffee is on the house.","accept":["Gracias. El tinto va por la casa.","Muchas gracias. El tinto lo invito yo.","Con gusto, y gracias. El tinto es de la casa."],"require":[],"focus":"g:subj-free-relatives","next":null}],"r":["g:future-promises","g:gender-articles","g:present-ar","g:questions","g:stem-boot","g:subj-free-relatives","g:subj-future-in-past","g:subj-wanting","g:that-clauses","g:verb-infinitive","p:lo-mejor-seria-que","p:me-da-rabia-me-indigna"],"d":null,"spare":true},
{"id":"sc-u51-a","unit":"u51","band":"B2","title":"Madrid en la mesa tres","brief":"You're Tomás, behind the counter. Lucía, a food blogger from Madrid, comes in first; her two friends are still at the hotel. She says hemos ido and he desayunado without noticing. You understand her, but you answer the way Colombians do: with ustedes, and with the plain past (ayer, hoy, esta mañana).","turns":[{"id":"t1","npc":"Lucía: Buenas. ¿Ya han abierto? Me han dicho que aquí hay buen café.","npcEn":"Lucía: Hello. Have you opened yet? They told me the coffee is good here.","intent":"Say yes, you opened a while ago (the Colombian way: ya abrimos), and ask what she would like to drink.","accept":["Sí, ya abrimos. ¿Qué quieres tomar?","Claro, abrimos a las siete. ¿Qué le sirvo?","Sí, abrimos hace un momento. ¿Qué vas a tomar?"],"require":[{"type":"question"},{"type":"avoidsAny","words":["hemos abierto"],"label":"answer the Colombian way: ya abrimos, not hemos abierto"}],"focus":"g:spain-pasts","next":"t2"},{"id":"t2","npc":"Lucía: Hoy he desayunado fatal en el hotel. Necesito un café ya.","npcEn":"Lucía: I had a terrible breakfast at the hotel today. I need a coffee right now.","intent":"Sympathise and ask her about her breakfast with the Colombian past (hoy desayunaste, not hoy has desayunado).","accept":["¿Hoy desayunaste mal? Qué pena. Aquí te preparamos algo.","Qué pena. ¿Dónde desayunaste?","Ay, ¿desayunaste mal hoy? Ahora te traigo algo rico."],"require":[{"type":"verbForm","inf":"desayunar","tense":"preterito","person":"tú","label":"use the plain past: desayunaste"}],"focus":"g:spain-pasts","next":"t3"},{"id":"t3","npc":"Lucía: Esta mañana mis amigas y yo hemos ido a la plaza de Bolívar y hemos comido unas empanadas. ¿Me entiendes bien? Hablo muy rápido.","npcEn":"Lucía: This morning my friends and I went to Plaza de Bolívar and had some empanadas. Do you understand me all right? I talk very fast.","intent":"Say you understand everything, and retell it the Colombian way: this morning they (she and her friends) went to the plaza and ate empanadas.","accept":["Te entiendo bien. Esta mañana fueron a la plaza y comieron empanadas.","Entiendo todo. O sea, esta mañana fueron a la plaza de Bolívar y comieron empanadas.","Claro que sí. Fueron a la plaza esta mañana y comieron empanadas, ¿cierto?"],"require":[{"type":"verbForm","inf":"ir","tense":"preterito","person":"ellos","label":"retell it with the plain past: fueron"}],"focus":"g:spain-pasts","next":"t4"},{"id":"t4","npc":"Lucía: ¡Qué rollo! He dejado el teléfono en el hotel y no puedo llamar a mis amigas.","npcEn":"Lucía: What a drag! I left my phone at the hotel and I can't call my friends.","intent":"Offer her your celular to make the call, and ask which hotel it is.","accept":["Usa mi celular. ¿En qué hotel están?","Llama desde mi celular, no hay problema. ¿Cómo se llama el hotel?","Toma mi celular. ¿Dónde queda el hotel?"],"require":[{"type":"question"},{"type":"containsWord","word":"celular","label":"say celular"}],"focus":"c:que-rollo-spain","next":"t5"},{"id":"t5","npc":"Lucía: Todo estaba riquísimo. Mañana volvemos con mis amigas del hotel.","npcEn":"Lucía: Everything was delicious. Tomorrow we'll be back with my friends from the hotel.","intent":"Thank them for coming and say you'll be waiting for them tomorrow.","accept":["Gracias por venir. Los espero mañana.","Muchas gracias por la visita. Aquí los espero.","Gracias a ustedes. Mañana los esperamos con un tinto."],"require":[{"type":"containsWord","word":"gracias","label":"say thanks"}],"focus":"g:spain-pasts","next":null}],"r":["c:que-rollo-spain","g:gender-articles","g:perfecto-experience","g:present-ar","g:spain-pasts","g:stem-boot"],"d":386},
{"id":"sc-u51-b","unit":"u51","band":"B2","title":"Un mes de prueba","brief":"You're Tomás, and Vale has just told you she accepted the trial month in Medellín. You're close, so use tú. Be glad for her, say what you would have done, and ask about the practical things.","turns":[{"id":"t1","npc":"Vale: Tomás, acepté el mes de prueba en Medellín. Me voy el lunes.","npcEn":"Vale: Tomás, I accepted the trial month in Medellín. I'm leaving on Monday.","intent":"Say you're happy for her and ask when she decided.","accept":["Me alegro por ti. ¿Cuándo lo decidiste?","¿Cuándo decidiste aceptar? Me alegro mucho por ti.","Qué bien. ¿Y cuándo decidiste irte?"],"require":[{"type":"question"},{"type":"verbForm","inf":"decidir","tense":"preterito","person":"tú","label":"ask with decidiste"}],"focus":"g:spain-pasts","next":"t2"},{"id":"t2","npc":"Vale: Anoche, después de hablar con mi mamá. Si lo hubiera sabido antes, te lo habría dicho. Perdona.","npcEn":"Vale: Last night, after talking to my mom. If I had known sooner, I would have told you. Sorry.","intent":"Tell her it's fine, and that if you had been in her place you would have done the same (use si yo hubiera estado).","accept":["No pasa nada. Si yo hubiera estado en tu lugar, habría hecho lo mismo.","Tranquila. Yo habría hecho lo mismo, si hubiera estado en tu lugar.","Si hubiera tenido tu oferta, también habría aceptado."],"require":[{"type":"regex","pattern":"\\bhubi(era|ese)\\b","flags":"iu","label":"use: si hubiera + participle"}],"focus":"g:se-form-recognition","next":"t3"},{"id":"t3","npc":"Vale: Mi abuela me escribió una carta muy formal: «Quisiera que tuvieses mucho cuidado en Medellín». Ella escribe así.","npcEn":"Vale: My grandmother wrote me a very formal letter: «I would like you to be very careful in Medellín». That's how she writes.","intent":"Ask whether tuviese means the same as tuviera.","accept":["¿Tuviese es lo mismo que tuviera?","¿Tuviese y tuviera son iguales?","Una pregunta: ¿tuviese y tuviera significan lo mismo?"],"require":[{"type":"question"},{"type":"containsWord","word":"tuviera","label":"ask about tuviera"}],"focus":"g:se-form-recognition","next":"t4"},{"id":"t4","npc":"Vale: Es igual. Casi nadie lo dice hablando, pero se ve en los libros y en las cartas de las abuelas. ¿Me ayudas con las cajas?","npcEn":"Vale: It's the same. Almost nobody says it out loud, but you see it in books and in grandmothers' letters. Will you help me with the boxes?","intent":"Say yes, and ask what time her bus leaves.","accept":["Claro. ¿A qué hora sale tu bus?","Te llevo las cajas. ¿A qué hora sale el bus?","Con gusto. ¿A qué hora sale el bus el lunes?"],"require":[{"type":"question"},{"type":"verbFormAny","inf":"salir","tense":"presente","label":"ask with sale"}],"focus":"g:spain-pasts","next":"t5"},{"id":"t5","npc":"Vale: A las seis. No te pongas triste, que vuelvo en un mes.","npcEn":"Vale: At six. Don't be sad, I'll be back in a month.","intent":"Tell her you'll miss her and that the café will be waiting for her.","accept":["Te voy a extrañar. Aquí te espera el café.","Voy a extrañarte mucho. El café te espera.","Te extrañaré, Vale. Vuelve pronto."],"require":[{"type":"regex","pattern":"extrañ","flags":"iu","label":"say you'll miss her: extrañar"}],"focus":"c:echar-de-menos-spain","next":null}],"r":["c:echar-de-menos-spain","g:direct-objects","g:gender-articles","g:present-ar","g:present-er-ir","g:se-form-recognition","g:spain-pasts","g:that-clauses"],"d":387},
{"id":"sc-u51-c","unit":"u51","band":"B2","title":"El sobrino de Sevilla","brief":"You're Tomás, and Don Hernando, courtly as ever, has a message from his nephew in Seville. Use usted with him. Translate Spain's Spanish into the Colombian way and say how you got used to all the accents.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Mi sobrino de Sevilla me escribió: \"Hoy he madrugado mucho y he ido al mercado.\" ¿Me lo dice usted en colombiano?","npcEn":"Hernando: Good morning, Tomás. My nephew in Seville wrote to me: \"Today I got up very early and went to the market.\" Can you tell me that in Colombian?","intent":"Say it the Colombian way: he got up early today and went to the market.","accept":["Hoy madrugó mucho y fue al mercado.","Dice que hoy madrugó y fue al mercado.","Aquí diríamos: hoy madrugó mucho y fue al mercado."],"require":[{"type":"verbForm","inf":"ir","tense":"preterito","person":"él/ella","label":"use the plain past: fue"}],"focus":"g:spain-pasts","next":"t2"},{"id":"t2","npc":"Hernando: También me escribió: ¡Qué rollo, tengo que trabajar el sábado! ¿Qué es un rollo?","npcEn":"Hernando: He also wrote to me: What a drag, I have to work on Saturday! What is a rollo?","intent":"Explain that it means something boring or a nuisance, like our qué pereza.","accept":["Es como decir qué pereza. Es algo aburrido.","Allá dicen qué rollo, y aquí decimos qué pereza.","Significa algo aburrido. Aquí diríamos qué pereza."],"require":[{"type":"containsWord","word":"pereza","label":"explain with pereza"}],"focus":"c:que-rollo-spain","next":"t3"},{"id":"t3","npc":"Hernando: ¿Sabe qué? Una vez un pasajero madrileño me dijo vale a todo durante el viaje. Yo pensé que me estaba preguntando cuánto valía la carrera.","npcEn":"Hernando: You know what? Once a passenger from Madrid said vale to everything during the ride. I thought he was asking me how much the fare was.","intent":"Explain that in Spain vale means OK; he wasn't asking about the price.","accept":["No, don Hernando. En España vale significa de acuerdo.","Allá vale es como decir listo. No hablaba del precio.","Vale quiere decir bueno, de acuerdo. No preguntaba el precio."],"require":[{"type":"containsWord","word":"vale","label":"mention vale"}],"focus":"c:vale-spain","next":"t4"},{"id":"t4","npc":"Hernando: ¡Y yo todo el viaje diciéndole el precio! Si lo hubiese sabido, le habría dado un tinto gratis. ¿Y usted, cómo hace con tantos acentos?","npcEn":"Hernando: And there I was the whole ride telling him the price! If I had known, I would have given him a free tinto. And how do you cope with so many accents?","intent":"Say you got used to understanding them all (use acostumbrarse a or adaptarse a).","accept":["Ya me acostumbré a todos los acentos.","Me costó adaptarme, pero ya los entiendo.","Con el tiempo me acostumbré a entenderlos."],"require":[{"type":"regex","pattern":"acostumbr|adapt","flags":"iu","label":"use acostumbrarse a or adaptarse a"}],"focus":"p:adaptarse-a","next":"t5"},{"id":"t5","npc":"Hernando: Mi sobrino jura que el café de su bar procede de Colombia. ¿Será verdad?","npcEn":"Hernando: My nephew swears that the coffee in his bar comes from Colombia. Can it be true?","intent":"Say it could be true, since a lot of coffee comes from Colombia (use procede de or proviene de), and offer him a tinto.","accept":["Puede ser. Mucho café procede de Colombia. ¿Le sirvo un tinto?","Es posible, mucho café proviene de aquí. ¿Un tinto, don Hernando?","Claro que sí, el mejor café procede de Colombia. Le sirvo un tinto."],"require":[{"type":"regex","pattern":"proced|provien","flags":"iu","label":"use procede de or proviene de"}],"focus":"p:proceder-de","next":null}],"r":["c:que-rollo-spain","c:vale-spain","g:direct-objects","g:gender-articles","g:present-er-ir","g:preterite-er-ir","g:questions","g:ser-identity","g:spain-pasts","g:that-clauses","p:adaptarse-a","p:proceder-de"],"d":447,"spare":true}
];
